// مستخرج من horofi-v11-9-29.html (WORD_SENTENCES) — جملة مثال لكل كلمة
export const WORD_SENTENCES = {"حر":"الْحَرُّ شِدَّةُ السَّخَانَةِ، نَشْرَبُ الْمَاءَ لِنَتَبَرَّدَ.","حل":"الْحَلُّ هُوَ الْإِجَابَةُ الصَّحِيحَةُ لِلْمَسْأَلَةِ.","شحم":"الشَّحْمُ مَادَّةٌ دُهْنِيَّةٌ تُوجَدُ فِي اللَّحْمِ.","رحم":"الرَّحِمُ عُضْوٌ فِي جِسْمِ الْأُمِّ تَنْمُو فِيهِ الْأَجِنَّةُ.","زحل":"زُحَلُ كَوْكَبٌ جَمِيلٌ لَهُ حَلَقَاتٌ مِنَ الثَّلْجِ.","نبح":"نَبَحَ الْكَلْبُ عِنْدَمَا سَمِعَ صَوْتًا غَرِيبًا.","سبح":"سَبِحَ الْوَلَدُ فِي الْبِرْكَةِ بِمَهَارَةٍ وَسُرْعَةٍ.","نطح":"نَطَحَ الْكَبْشُ الْآخَرَ بِقُرُونِهِ الْقَوِيَّةِ.","جرح":"الْجُرْحُ إِصَابَةٌ فِي الْجِلْدِ تَحْتَاجُ إِلَى عِنَايَةٍ.","مرح":"الْمَرَحُ فَرَحٌ وَلَعِبٌ، وَالطُّفُولَةُ أَجْمَلُ أَوْقَاتِهِ.","صرح":"الصَّرْحُ بِنَاءٌ ضَخْمٌ شَامِخٌ يُرَى مِنْ بَعِيدٍ.","حقل":"الْحَقْلُ أَرْضٌ زِرَاعِيَّةٌ يَزْرَعُ فِيهَا الْفَلَّاحُ.","حكم":"الْحُكْمُ قَرَارٌ يُصْدِرُهُ الْقَاضِي بِالْعَدْلِ.","صحن":"الصَّحْنُ إِنَاءٌ مُسْتَدِيرٌ نَضَعُ فِيهِ الطَّعَامَ.","فحم":"الْفَحْمُ مَادَّةٌ سَوْدَاءُ تُشْعَلُ لِإِنْتَاجِ الْحَرَارَةِ.","وحدة":"الْوَحْدَةُ تَعْنِي أَنْ تَكُونَ وَحِيدًا بِلَا رِفَاقٍ.","أحمد":"أَحْمَدُ اسْمٌ عَرَبِيٌّ جَمِيلٌ مَعْنَاهُ كَثِيرُ الْحَمْدِ.","زحمة":"الزَّحْمَةُ تَجَمُّعُ النَّاسِ فِي مَكَانٍ وَاحِدٍ.","صلح":"صَلَحَ الشَّيْءُ إِذَا صَارَ جَيِّدًا وَنَافِعًا.","قبح":"قَبُحَ الشَّيْءُ إِذَا كَانَ غَيْرَ جَمِيلٍ.","نضح":"نَضَحَ الزَّرَّاعُ النَّبَاتَ بِالْمَاءِ لِيَنْمُوَ.","قدح":"الْقَدَحُ كُوبٌ كَبِيرٌ نَشْرَبُ فِيهِ الْمَاءَ أَوِ الشَّايَ.","رمح":"الرُّمْحُ سِلَاحٌ طَوِيلٌ كَانَ يَسْتَخْدِمُهُ الْفُرْسَانُ.","حديقة":"الْحَدِيقَةُ مَكَانٌ جَمِيلٌ مَلِيءٌ بِالزُّهُورِ وَالْأَشْجَارِ.","حضارة":"الْحَضَارَةُ رُقِيُّ الْإِنْسَانِ فِي الْعِلْمِ وَالثَّقَافَةِ.","محطة":"الْمَحَطَّةُ مَكَانٌ تَتَوَقَّفُ فِيهِ الْقِطَارَاتُ وَالْحَافِلَاتُ.","مشحون":"الشَّاحِنُ مَشْحُونٌ بِالْبَضَاعَةِ وَعَلَى وَشْكِ الْإِقْلَاعِ.","وحشية":"الْوَحْشِيَّةُ طَبِيعَةُ الْحَيَوَانَاتِ الْبَرِّيَّةِ الشَّرِسَةِ.","أحلام":"الْأَحْلَامُ صُوَرٌ نَرَاهَا وَنَحْنُ نِيَامٌ فِي اللَّيْلِ.","رحلات":"الرِّحَلَاتُ سَفَرٌ إِلَى أَمَاكِنَ جَدِيدَةٍ لِلتَّعَلُّمِ.","سامح":"سَامَحَ الْوَلَدُ أَخَاهُ وَعَادَا صَدِيقَيْنِ حَمِيمَيْنِ.","كافح":"كَافَحَ الطَّالِبُ بِجَدٍّ حَتَّى نَالَ أَعْلَى الدَّرَجَاتِ.","صافح":"صَافَحَ الضَّيْفُ الْمُضِيفَ وَشَكَرَهُ عَلَى الْكَرَمِ.","جراح":"الْجِرَاحُ آلَامٌ وَإِصَابَاتٌ تَحْتَاجُ إِلَى رِعَايَةٍ طِبِّيَّةٍ.","أفراح":"الْأَفْرَاحُ مُنَاسَبَاتٌ سَعِيدَةٌ يَجْتَمِعُ فِيهَا الْأَهْلُ.","أرواح":"الْأَرْوَاحُ مَا يَحْيَا بِهِ الْجَسَدُ، وَهِيَ أَمَانَةُ اللهِ.","خل":"الْخَلُّ سَائِلٌ حَامِضٌ يُضَافُ إِلَى السَّلَطَاتِ.","خف":"الْخُفُّ حِذَاءٌ خَفِيفٌ يُلْبَسُ دَاخِلَ الْبَيْتِ.","فخر":"الْفَخْرُ شُعُورٌ جَمِيلٌ بِالرِّضَا عَنِ الْإِنْجَازِ.","بخل":"الْبُخْلُ عَدَمُ الْكَرَمِ، وَالْكَرَمُ أَجْمَلُ وَأَفْضَلُ.","شخص":"الشَّخْصُ الْإِنْسَانُ بِمَا لَهُ مِنْ صِفَاتٍ وَمَشَاعِرَ.","رخو":"الرَّخْوُ الشَّيْءُ اللَّيِّنُ الَّذِي يَنْضَغِطُ بِسُهُولَةٍ.","ذخر":"الذُّخْرُ مَا يُدَّخَرُ وَيُحْتَفَظُ بِهِ لِوَقْتِ الْحَاجَةِ.","زخم":"الزَّخَمُ قُوَّةٌ وَكَثَافَةٌ فِي الْحَرَكَةِ أَوِ الْعَمَلِ.","سلخ":"سَلَخَ الْجَزَّارُ جِلْدَ الشَّاةِ بَعْدَ الذَّبْحِ.","نسخ":"نَسَخَ التِّلْمِيذُ الدَّرْسَ مِنَ السَّبُّورَةِ بِعِنَايَةٍ.","فلخ":"فَلَخَ الْبَطَلُ خَصْمَهُ بِضَرْبَةٍ قَوِيَّةٍ.","صرخ":"صَرَخَ الطِّفْلُ بِصَوْتٍ عَالٍ لِيُنَبِّهَ أُمَّهُ.","شرخ":"الشَّرْخُ شَقٌّ صَغِيرٌ فِي جِدَارٍ أَوْ زُجَاجٍ.","خيار":"الْخِيَارُ خَضْرَاءُ مُنْعِشَةٌ تُؤْكَلُ فِي السَّلَطَةِ.","خلال":"خِلَالَ الصَّيْفِ نَذْهَبُ إِلَى الشَّاطِئِ وَنَسْبَحُ.","خطاب":"الْخِطَابُ كَلَامٌ مُهِمٌّ يُلْقِيهِ الْمُتَحَدِّثُ أَمَامَ الْجَمْهُورِ.","بخار":"الْبُخَارُ مَاءٌ تَحَوَّلَ إِلَى غَازٍ بِفِعْلِ الْحَرَارَةِ.","فخار":"الْفَخَّارُ أَوَانٍ تُصْنَعُ مِنَ الطِّينِ وَتُحْرَقُ بِالنَّارِ.","مخدة":"الْمِخَدَّةُ وِسَادَةٌ لَيِّنَةٌ نَضَعُ عَلَيْهَا رَأْسَنَا.","وخيم":"الْوَضْعُ وَخِيمٌ إِذَا كَانَ خَطِيرًا وَيَسْتَدْعِي الِاهْتِمَامَ.","رخام":"الرُّخَامُ حَجَرٌ صَلْبٌ جَمِيلٌ يُزَيَّنُ بِهِ الْبِنَاءُ.","ذخيرة":"الذَّخِيرَةُ رَصَاصُ السِّلَاحِ أَوِ الطَّاقَةُ الْمَخْزُونَةُ.","فسخ":"فَسَخَ الطَّرَفَانِ الْعَقْدَ بَعْدَ الِاتِّفَاقِ.","صارخ":"صَارِخٌ مَنْ يَصْرُخُ بِصَوْتٍ عَالٍ مُسْتَغِيثًا أَوْ مُحَذِّرًا.","فارخ":"الْفَارِخُ صَغِيرُ الطَّائِرِ النَّاضِجُ قَلِيلًا.","مؤرخ":"الْمُؤَرِّخُ عَالِمٌ يَدْرُسُ أَحْدَاثَ التَّارِيخِ وَيُدَوِّنُهَا.","خليفة":"الْخَلِيفَةُ حَاكِمُ الْمُسْلِمِينَ بَعْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.","خريطة":"الْخَرِيطَةُ رَسْمٌ يُوضِّحُ شَكْلَ الْأَرَاضِي وَالدُّوَلِ.","خزينة":"الْخَزِينَةُ مَكَانٌ آمِنٌ لِحِفْظِ الْأَمْوَالِ وَالثَّرَوَاتِ.","مخزون":"الْمَخْزُونُ مَا يُحْتَفَظُ بِهِ مِنْ بَضَائِعَ أَوْ مُؤَنٍ.","مخترع":"الْمُخْتَرَعُ شَيْءٌ جَدِيدٌ أَبْدَعَهُ عَقْلُ الْإِنْسَانِ.","تخصص":"التَّخَصُّصُ التَّعَمُّقُ فِي عِلْمٍ أَوْ مَجَالٍ بِعَيْنِهِ.","رخاوة":"الرَّخَاوَةُ صِفَةُ الشَّيْءِ اللَّيِّنِ الَّذِي لَا يَتَمَاسَكُ.","زخارف":"الزَّخَارِفُ نُقُوشٌ وَأَشْكَالٌ جَمِيلَةٌ تُزَيِّنُ الْجُدْرَانَ.","وخامة":"الْوَخَامَةُ شِدَّةُ الضَّرَرِ أَوِ الْخَطَرِ فِي الْأَمْرِ.","تمسخ":"تَمَسَّخَ الشَّيْءُ إِذَا تَغَيَّرَتْ صُورَتُهُ تَغَيُّرًا كَامِلًا.","تسلخ":"تَسَلَّخَتْ طَبَقَةُ الْجِلْدِ بَعْدَ التَّعَرُّضِ لِلشَّمْسِ.","أفراخ":"الْأَفْرَاخُ جَمْعُ فَرْخٍ، وَهِيَ صِغَارُ الطُّيُورِ الصَّغِيرَةُ.","تواريخ":"التَّوَارِيخُ أَحْدَاثٌ مُسَجَّلَةٌ مِنَ الْمَاضِي نَتَعَلَّمُ مِنْهَا.","مؤارخ":"الْمُؤَارِخُ مَنْ يَكْتُبُ التَّارِيخَ وَيُحَقِّقُ فِي أَحْدَاثِهِ.","سوق":"السُّوقُ مَكَانٌ يَبِيعُ فِيهِ التُّجَّارُ بَضَائِعَهُمْ.","سيف":"السَّيْفُ سِلَاحٌ حَادٌّ ذُو حَدَّيْنِ كَانَ يُقَاتَلُ بِهِ.","بسم":"بَسَمَ الْوَلَدُ فَرَحًا حِينَ رَأَى هَدِيَّتَهُ الْجَمِيلَةَ.","تسع":"التِّسْعُ عَدَدٌ يَأْتِي بَعْدَ الثَّمَانِيَةِ وَقَبْلَ الْعَشَرَةِ.","نسر":"النَّسْرُ طَائِرٌ ضَخْمٌ يُحَلِّقُ عَالِيًا فَوْقَ الْجِبَالِ.","وسخ":"الْوَسَخُ أَتْرِبَةٌ وَأَقْذَارٌ يَجِبُ إِزَالَتُهَا بِالتَّنْظِيفِ.","رسن":"الرَّسَنُ حَبْلٌ يُرْبَطُ بِهِ الْحَيَوَانُ لِيُقَادَ.","وسم":"وَسَمَ الرَّاعِي الْمَاشِيَةَ بِعَلَامَةٍ تَدُلُّ عَلَى مَالِكِهَا.","حبس":"حَبَسَ الشُّرْطِيُّ الْمُجْرِمَ فِي السِّجْنِ جَزَاءً لِعَمَلِهِ.","لمس":"لَمَسَ الطِّفْلُ الْقِطَّةَ بِيَدِهِ فَشَعَرَ بِنُعُومَةِ فَرْوِهَا.","كنس":"كَنَسَتِ الْأُمُّ الْأَرْضَ بِالْمِكْنَسَةِ حَتَّى لَمَعَتْ.","كأس":"الْكَأْسُ إِنَاءٌ زُجَاجِيٌّ نَشْرَبُ فِيهِ الْعَصِيرَ.","رأس":"الرَّأْسُ أَعْلَى الْجِسْمِ، فِيهِ الْعَقْلُ وَالْحَوَاسُّ.","حدس":"حَدَسَ الطِّفْلُ بِالْإِجَابَةِ الصَّحِيحَةِ قَبْلَ الشَّرْحِ.","سباق":"السِّبَاقُ مُنَافَسَةٌ سَرِيعَةٌ بَيْنَ مُتَسَابِقِينَ لِلْفَوْزِ.","بسمة":"الْبُسْمَةُ ابْتِسَامَةٌ صَغِيرَةٌ تُضِيءُ الْوَجْهَ وَالْقَلْبَ.","تسمية":"التَّسْمِيَةُ اخْتِيَارُ اسْمٍ مُنَاسِبٍ لِشَخْصٍ أَوْ شَيْءٍ.","وساد":"الْوِسَادُ مِخَدَّةٌ تَقِلِيدِيَّةٌ مِنَ الْقُطْنِ أَوِ الصُّوفِ.","نفس":"النَّفْسُ رُوحُ الْإِنْسَانِ وَجَوْهَرُهُ الدَّاخِلِيُّ الْعَمِيقُ.","عكس":"الْعَكْسُ هُوَ الضِّدُّ؛ عَكْسُ الْكَبِيرِ صَغِيرٌ.","نحس":"النَّحْسُ السُّوءُ وَالشُّؤْمُ، وَالتَّفَاؤُلُ أَفْضَلُ مِنْهُ.","قاموس":"الْقَامُوسُ كِتَابٌ يَشْرَحُ مَعَانِيَ الْكَلِمَاتِ بِتَفْصِيلٍ.","ناموس":"النَّامُوسُ الْقَانُونُ وَالشَّرِيعَةُ، وَيُقَالُ لِلْبَعُوضِ أَيْضًا.","حراس":"الْحُرَّاسُ جَمْعُ حَارِسٍ، وَهُمُ الَّذِينَ يَحْمُونَ الْمَكَانَ.","سنجاب":"السِّنْجَابُ حَيَوَانٌ صَغِيرٌ يَجْمَعُ الْجَوْزَ لِلشِّتَاءِ.","سلحفاة":"السُّلَحْفَاةُ زَاحِفٌ بَطِيءٌ يَحْمِلُ بَيْتَهُ عَلَى ظَهْرِهِ.","سلسلة":"السِّلْسِلَةُ حَلَقَاتٌ مُتَّصِلَةٌ، أَوْ أَحْدَاثٌ مُتَتَابِعَةٌ.","تسلية":"التَّسْلِيَةُ اللَّهْوُ الْمُمْتِعُ الَّذِي يُرِيحُ الْعَقْلَ وَالرُّوحَ.","منسوب":"الْمَنْسُوبُ مَا يُنْسَبُ إِلَى شَخْصٍ أَوْ مَكَانٍ بِعَيْنِهِ.","مستشفى":"الْمُسْتَشْفَى مَكَانٌ يَتَلَقَّى فِيهِ الْمَرِيضُ الْعِنَايَةَ الطِّبِّيَّةَ.","وسوسة":"الْوَسْوَسَةُ حَدِيثُ النَّفْسِ السِّلْبِيُّ الَّذِي يُقَلِّلُ الثِّقَةَ.","رسائل":"الرَّسَائِلُ جَمْعُ رِسَالَةٍ، وَهِيَ كُتُبٌ وَخِطَابَاتٌ.","أساطير":"الْأَسَاطِيرُ قِصَصٌ قَدِيمَةٌ تَحْكِي عَنِ الْآلِهَةِ وَالْأَبْطَالِ.","تنفس":"تَنَفَّسَ الْغَرِيقُ الْهَوَاءَ بِعُمْقٍ حِينَ خَرَجَ مِنَ الْمَاءِ.","مجلس":"الْمَجْلِسُ مَكَانُ الِاجْتِمَاعِ وَالتَّشَاوُرِ وَاتِّخَاذِ الْقَرَارَاتِ.","مدرس":"الْمُدَرِّسُ مَنْ يُعَلِّمُ الطُّلَّابَ الْعُلُومَ وَالْمَعَارِفَ.","تأسس":"تَأَسَّسَتِ الْمَدْرَسَةُ قَبْلَ مِئَةِ عَامٍ وَلَا تَزَالُ تَزْدَهِرُ.","ترأس":"تَرَأَّسَ الطَّالِبُ الْمُجْتَهِدُ مَجْلِسَ الطُّلَّابِ بِجَدَارَةٍ.","تهرس":"تَهَرَّسَتِ الْبُذُورُ فِي الْمِهْرَاسِ حَتَّى صَارَتْ مَسْحُوقًا.","شب":"الشَّبُّ مَعْدِنٌ أَبْيَضُ يُسْتَخْدَمُ فِي الصِّبَاغَةِ وَالطِّبِّ.","شق":"الشَّقُّ فَتْحَةٌ ضَيِّقَةٌ فِي جِدَارٍ أَوْ أَرْضٍ.","شن":"الشَّنُّ وِعَاءٌ جِلْدِيٌّ قَدِيمٌ يُحْفَظُ فِيهِ الْمَاءُ.","بشر":"الْبَشَرُ جَمِيعُ النَّاسِ عَلَى اخْتِلَافِ أَلْوَانِهِمْ وَلُغَاتِهِمْ.","نشط":"نَشِطَ الْوَلَدُ بَعْدَ نَوْمٍ عَمِيقٍ فَأَسْرَعَ إِلَى اللَّعِبِ.","كشك":"الْكُشْكُ بُسْطَةٌ صَغِيرَةٌ تُبَاعُ فِيهَا الْكُتُبُ وَالصُّحُفُ.","وشم":"الْوَشْمُ رَسْمٌ يُطْبَعُ عَلَى الْجِلْدِ بِإِبْرَةٍ وَصِبْغَةٍ.","رشف":"رَشَفَ الطِّفْلُ الشَّرَابَ بِهُدُوءٍ وَتَلَذُّذٍ.","دشت":"الدَّشْتُ سَهْلٌ وَاسِعٌ يَمْتَدُّ بِلَا أَشْجَارٍ.","نقش":"نَقَشَ الْفَنَّانُ أَشْكَالًا جَمِيلَةً عَلَى الْخَشَبِ.","بطش":"بَطَشَ الْبَطَلُ بِخَصْمِهِ فَأَسْقَطَهُ أَرْضًا.","نبش":"نَبَشَ الْوَلَدُ الْأَرْضَ بِيَدَيْهِ بَحْثًا عَنِ الدِّيدَانِ.","عرش":"الْعَرْشُ كُرْسِيُّ الْمَلِكِ الَّذِي يَجْلِسُ عَلَيْهِ.","ريش":"الرِّيشُ غِطَاءٌ خَفِيفٌ يُحَمِّي الطَّائِرَ مِنَ الْبَرْدِ.","حوش":"الْحَوْشُ فِنَاءٌ مَكْشُوفٌ أَمَامَ الْبَيْتِ يَلْعَبُ فِيهِ الْأَطْفَالُ.","شعاع":"شُعَاعُ الشَّمْسِ يُضِيءُ الْغُرْفَةَ وَيَمْنَحُ الدِّفْءَ.","شتاء":"الشِّتَاءُ فَصْلٌ بَارِدٌ تَتَسَاقَطُ فِيهِ الْأَمْطَارُ.","بشير":"بَشِيرٌ اسْمٌ عَرَبِيٌّ مَعْنَاهُ حَامِلُ الْبُشْرَى السَّعِيدَةِ.","نشيد":"النَّشِيدُ أُغْنِيَةٌ تُغَنَّى فِي الِاحْتِفَالَاتِ الْوَطَنِيَّةِ.","وشاح":"الْوِشَاحُ قِطْعَةُ قُمَاشٍ تَضَعُهَا الْمَرْأَةُ زِينَةً.","رشاش":"الرَّشَّاشُ أَدَاةٌ تُرَشُّ بِهَا الْمِيَاهُ عَلَى النَّبَاتَاتِ.","وشوش":"وَشْوَشَ الصَّدِيقُ فِي أُذُنِ صَاحِبِهِ كَلَامًا سِرِّيًّا.","نفش":"نَفَشَ الطَّائِرُ رِيشَهُ فِي الْبَرْدِ لِيَحْفَظَ دِفْءَهُ.","رفش":"رَفَشَ الْعَامِلُ الرَّمْلَ بِالْمِجْرَفَةِ لِتَسْوِيَةِ الطَّرِيقِ.","أحراش":"الْأَحْرَاشُ غَابَاتٌ كَثِيفَةُ الْأَشْجَارِ تَسْكُنُهَا الطُّيُورُ.","خراش":"الْخِرَاشُ جُرُوحٌ خَفِيفَةٌ عَلَى الْجِلْدِ.","أعشاش":"الْأَعْشَاشُ بُيُوتُ الطُّيُورِ مِنَ الْأَغْصَانِ.","شخصية":"الشَّخْصِيَّةُ مَجْمُوعُ صِفَاتِ الْإِنْسَانِ الَّتِي تُمَيِّزُهُ.","شهادة":"الشَّهَادَةُ وَثِيقَةٌ رَسْمِيَّةٌ.","شعرية":"الشِّعْرِيَّةُ جَمَالُ الْكَلِمَاتِ وَتَنَاغُمُهَا فِي الشِّعْرِ.","تشجيع":"التَّشْجِيعُ دَفْعُ الشَّخْصِ نَحْوَ الْأَمَامِ بِالْكَلِمَاتِ الطَّيِّبَةِ.","بشرية":"الْبَشَرِيَّةُ مَجْمُوعُ الْبَشَرِ عَلَى الْأَرْضِ.","وشوشة":"الْوَشْوَشَةُ الْكَلَامُ الْخَفِيُّ الَّذِي يَسْمَعُهُ الْمَقْرَبُونَ.","رشاقة":"الرَّشَاقَةُ الْخِفَّةُ وَالتَّنَاسُقُ فِي حَرَكَاتِ الْجِسْمِ.","دشداشة":"الدِّشْدَاشَةُ ثَوْبٌ طَوِيلٌ يَرْتَدِيهِ الرِّجَالُ فِي الْخَلِيجِ.","توحش":"تَوَحَّشَ مَنْ عَاشَ وَحِيدًا بَعِيدًا عَنِ النَّاسِ.","انتعش":"اِنْتَعَشَ الْمَرِيضُ بَعْدَ الْعِلَاجِ وَعَادَ إِلَى نَشَاطِهِ.","تفحش":"تَفَحَّشَ الْكَلَامُ حِينَ يَخْرُجُ عَنِ الْحُدُودِ الْمَقْبُولَةِ.","أفراش":"الْأَفْرَاشُ جَمْعُ فِرَاشٍ وَهِيَ أَغْطِيَةُ النَّوْمِ.","دراويش":"الدَّرَاوِيشُ مُتَصَوِّفُونَ يَذْكُرُونَ اللهَ بِحَرَكَاتٍ خَاصَّةٍ.","صح":"صَحَّ الطِّفْلُ مِنْ مَرَضِهِ وَعَادَ يَلْعَبُ بِنَشَاطٍ.","صف":"الصَّفُّ تَرْتِيبٌ يَقِفُ فِيهِ النَّاسُ وَاحِدًا خَلْفَ الْآخَرِ.","صد":"الصَّدُّ مَنْعُ الشَّيْءِ مِنَ الْوُصُولِ بِالتَّصَدِّي لَهُ.","قصب":"الْقَصَبُ نَبَاتٌ طَوِيلٌ يَنْمُو قُرْبَ الْمَاءِ.","عصب":"الْعَصَبُ خُيُوطٌ دَقِيقَةٌ تَنْقُلُ الْإِحْسَاسَ إِلَى الدِّمَاغِ.","نصح":"نَصَحَ الطَّبِيبُ الْمَرِيضَ بِالرَّاحَةِ وَشُرْبِ الْمَاءِ.","وصف":"الْوَصْفُ تَصْوِيرُ الشَّيْءِ بِالْكَلِمَاتِ.","رصد":"رَصَدَ الْعَالِمُ حَرَكَةَ النُّجُومِ بِمِنْظَارِهِ.","وصم":"الْوَصْمُ عَيْبٌ يُلْحَقُ بِسُمْعَةِ الشَّخْصِ.","نقص":"نَقَصَ الْمَاءُ فِي الْوِعَاءِ بَعْدَ أَنْ شَرِبَ مِنْهُ الْجَمِيعُ.","خلص":"خَلَصَ الْمُسَافِرُ مِنْ عَنَاءِ الطَّرِيقِ حِينَ وَصَلَ إِلَى بَيْتِهِ.","قلص":"قَلَّصَ التَّاجِرُ نَفَقَاتِهِ لِتَوْفِيرِ الْمَالِ.","رص":"الرَّصُّ تَرْتِيبُ الْأَشْيَاءِ بِإِحْكَامٍ جَنْبًا إِلَى جَنْبٍ.","فرص":"الْفُرَصُ مَوَاقِفُ مُنَاسِبَةٌ يَجِبُ اغْتِنَامُهَا.","برص":"الْبَرَصُ مَرَضٌ جِلْدِيٌّ يُسَبِّبُ بُقَعًا بَيْضَاءَ.","صاروخ":"الصَّارُوخُ مُرْكَبَةٌ تُطْلَقُ لِلْوُصُولِ إِلَى الْفَضَاءِ.","صنوبر":"الصَّنَوْبَرُ شَجَرَةٌ دَائِمَةُ الْخُضْرَةِ تُزَيِّنُ الْجِبَالَ.","بصيرة":"الْبَصِيرَةُ الْفِطْنَةُ وَالْقُدْرَةُ عَلَى فَهْمِ الْحَقِيقَةِ.","نصيحة":"النَّصِيحَةُ كَلَامٌ صَادِقٌ يُقَالُ بِحُبٍّ لِمَنْ نُحِبُّهُ.","تصفيق":"التَّصْفِيقُ ضَرْبُ الْكَفَّيْنِ تَعْبِيرًا عَنِ الْإِعْجَابِ.","وصية":"الْوَصِيَّةُ طَلَبٌ يَتْرُكُهُ الشَّخْصُ قَبْلَ وَفَاتِهِ.","رصانة":"الرَّصَانَةُ الْمَتَانَةُ وَالثَّبَاتُ فِي الرَّأْيِ.","وصفة":"الْوَصْفَةُ تَعْلِيمَاتٌ يَكْتُبُهَا الطَّبِيبُ لِعِلَاجِ الْمَرِيضِ.","تلصص":"تَلَصَّصَ الْوَلَدُ مِنْ وَرَاءِ الْبَابِ لِيَرَى مَا يَجْرِي.","تمصمص":"تَمَصْمَصَ الطِّفْلُ الْحَلَوَى حَتَّى تَشَرَّبَ طَعْمَهَا.","أرخص":"أَرْخَصَ التَّاجِرُ سِعْرَ الْبُضَاعَةِ لِجَذْبِ الزَّبَائِنِ.","ترخص":"تَرَخَّصَ الطَّالِبُ بِغِيَابٍ لِحُضُورِ مُنَاسَبَةٍ عَائِلِيَّةٍ.","تراص":"تَرَاصَّ الْجُنُودُ فِي صَفٍّ مَتِينٍ لَا فُرْجَةَ فِيهِ.","صلصال":"الصَّلْصَالُ طِينٌ لَزِجٌ يُشَكَّلُ مِنْهُ الْفَخَّارُ.","صومعة":"الصَّوْمَعَةُ بُرْجٌ طَوِيلٌ يَنْطَلِقُ مِنْهُ صَوْتُ الْأَذَانِ.","صرامة":"الصَّرَامَةُ الْحَزْمُ وَالتَّمَسُّكُ بِالْمَبَادِئِ.","تصوير":"التَّصْوِيرُ الْتِقَاطُ الصُّوَرِ بِالْكَامِيرَا.","تصميم":"التَّصْمِيمُ رَسْمُ خِطَّةٍ لِصُنْعِ شَيْءٍ مَا.","مصباح":"الْمِصْبَاحُ أَدَاةٌ تُضِيءُ الظَّلَامَ.","وصاية":"الْوَصَايَةُ تَوَلِّي رِعَايَةِ شَخْصٍ نِيَابَةً عَنْ غَيْرِهِ.","رصيد":"الرَّصِيدُ الْمَبْلَغُ الْمَالِيُّ فِي الْحِسَابِ الْبَنْكِيِّ.","وصوصة":"الْوَصْوَصَةُ النَّظَرُ مِنْ ثُقْبٍ ضَيِّقٍ بِعَيْنٍ وَاحِدَةٍ.","ترقص":"تَرَقَّصَ الطِّفْلُ فَرَحًا حِينَ سَمِعَ الْمُوسِيقَى.","تملص":"تَمَلَّصَ مِنَ الْمَأْزِقِ بِكَلِمَاتٍ بَارِعَةٍ.","تقلص":"تَقَلَّصَ عَدَدُ الطُّلَّابِ بَعْدَ انْتِهَاءِ الْإِجَازَةِ.","إخلاص":"الْإِخْلَاصُ أَدَاءُ الْعَمَلِ بِصِدْقٍ وَإِتْقَانٍ.","اختصاص":"الِاخْتِصَاصُ الْمَجَالُ الَّذِي يَتَفَوَّقُ فِيهِ الشَّخْصُ.","انتقاص":"الِانْتِقَاصُ التَّقْلِيلُ مِنْ قَدْرِ الشَّيْءِ بِغَيْرِ حَقٍّ.","ضب":"الضَّبُّ حَيَوَانٌ زَاحِفٌ يَعِيشُ فِي الصَّحْرَاءِ الْعَرَبِيَّةِ.","ضرب":"ضَرَبَ الطَّالِبُ الْمِسْمَارَ بِالْمِطْرَقَةِ.","ضرس":"الضِّرْسُ سِنٌّ خَلْفِيَّةٌ تَطْحَنُ الطَّعَامَ فِي الْفَمِ.","غضب":"الْغَضَبُ شُعُورٌ قَوِيٌّ يَجِبُ تَعَلُّمُ السَّيْطَرَةِ عَلَيْهِ.","قضم":"قَضَمَ الطِّفْلُ التُّفَّاحَةَ بِأَسْنَانِهِ الصَّغِيرَةِ.","رضع":"رَضَعَ الرَّضِيعُ مِنْ أُمِّهِ فَشَعَرَ بِالدِّفْءِ.","وضح":"وَضَحَتِ الْحَقِيقَةُ بَعْدَ التَّحْقِيقِ.","رضي":"رَضِيَ الْأَبُ عَنِ ابْنِهِ حِينَ جَاءَ بِنَتِيجَةٍ مُتَفَوِّقَةٍ.","نقض":"نَقَضَ الْعُمَّالُ الْبِنَاءَ الْقَدِيمَ.","غمض":"غَمَضَتِ الْمَسْأَلَةُ عَلَى الطَّالِبِ.","حمض":"حَمُضَ الطَّعَامُ بَعْدَ تَرْكِهِ فِي الشَّمْسِ.","غرض":"الْغَرَضُ الْهَدَفُ الَّذِي يَسْعَى الْإِنْسَانُ إِلَى تَحْقِيقِهِ.","فرض":"فَرَضَ الْمُعَلِّمُ قَوَاعِدَ النِّظَامِ لِيَسُودَ الْهُدُوءُ.","عرض":"الْعَرَضُ مَا يَطْرَأُ عَارِضًا وَلَا يَدُومُ.","ضرورة":"الضَّرُورَةُ الْحَاجَةُ الْمُلِحَّةُ الَّتِي لَا تُتَجَاهَلُ.","ضمانة":"الضَّمَانَةُ الْتِزَامٌ بِضَمَانِ شَيْءٍ.","ضوابط":"الضَّوَابِطُ الْقَوَاعِدُ الَّتِي تُنَظِّمُ السُّلُوكَ.","تضامن":"التَّضَامُنُ الْوُقُوفُ مَعًا فِي مُوَاجَهَةِ الصِّعَابِ.","تضحية":"التَّضْحِيَةُ التَّنَازُلُ عَنِ الرَّاحَةِ خِدْمَةً لِهَدَفٍ نَبِيلٍ.","مضمار":"الْمِضْمَارُ مَيْدَانُ السِّبَاقِ.","وضوح":"الْوُضُوحُ صِفَةُ الشَّيْءِ الْبَيِّنِ الَّذِي لَا يَحْتَاجُ شَرْحًا.","رضاعة":"الرَّضَاعَةُ تَغْذِيَةُ الرَّضِيعِ بِحَلِيبِ الْأُمِّ.","وضاءة":"الْوَضَاءَةُ النَّقَاءُ وَالنَّظَافَةُ وَالْحُسْنُ.","تناقض":"التَّنَاقُضُ وُجُودُ قَوْلَيْنِ مُتَعَارِضَيْنِ.","تقبض":"تَقَبَّضَ الْقَطُّ مُسْتَعِدًّا لِلْقَفْزِ.","تربض":"تَرَبَّضَ الصَّيَّادُ يَنْتَظِرُ الْفُرْصَةَ.","تعارض":"تَعَارَضَتِ الرِّوَايَتَانِ وَلَمْ يَتَّفِقَا.","تفاوض":"تَفَاوَضَ الطَّرَفَانِ حَتَّى تَوَصَّلَا لِاتِّفَاقٍ.","تراكض":"تَرَاكَضَ الْأَوْلَادُ مُتَنَافِسِينَ عَلَى الْفَوْزِ.","ضمادة":"الضَّمَادَةُ شَاشَةٌ طِبِّيَّةٌ تُوضَعُ عَلَى الْجُرْحِ.","ضاحية":"الضَّاحِيَةُ مَنْطِقَةٌ سَكَنِيَّةٌ خَارِجَ الْمَدِينَةِ.","ضحالة":"الضَّحَالَةُ قِلَّةُ الْعُمْقِ فِي الْمَاءِ أَوِ الْفِكْرِ.","تضليل":"التَّضْلِيلُ إِيهَامُ الشَّخْصِ بِمَعْلُومَاتٍ كَاذِبَةٍ.","مضطرب":"الْمُضْطَرِبُ مَنْ يَعِيشُ قَلَقًا فِي أَفْكَارِهِ.","تضمين":"التَّضْمِينُ إِدْرَاجُ فِكْرَةٍ ضِمْنَ نَصٍّ أَكْبَرَ.","رضوخ":"الرُّضُوخُ الْقَبُولُ الْمُرْغَمُ بِشَيْءٍ لَا يُرِيدُهُ.","وضاعة":"الْوَضَاعَةُ الْحَقَارَةُ وَانْعِدَامُ الْكَرَامَةِ.","رضيعة":"الرَّضِيعَةُ طِفْلَةٌ لَا تَزَالُ تَتَغَذَّى بِحَلِيبِ أُمِّهَا.","تشبض":"تَشَبَّضَ الطِّفْلُ بِيَدِ أُمِّهِ رَافِضًا أَنْ يَتْرُكَهَا.","انقبض":"اِنْقَبَضَ قَلْبُهُ أَلَمًا حِينَ سَمِعَ خَبَرَ الْفِرَاقِ.","استعض":"اِسْتَعَاضَ عَنِ الْحُزْنِ بِقَصِيدَةٍ أَبَثَّ فِيهَا مَشَاعِرَهُ.","مفترض":"الْمُفْتَرَضُ الشَّيْءُ الَّذِي يُؤْخَذُ كَأَسَاسٍ.","اعتراض":"الِاعْتِرَاضُ رَفْضُ الرَّأْيِ وَإِبْدَاءُ الْمُخَالَفَةِ.","استعراض":"الِاسْتِعْرَاضُ عَرْضُ الْقُدُرَاتِ أَمَامَ الْجَمْهُورِ.","طن":"الطَّنُّ صَوْتٌ رَنَّانٌ يَصْدُرُ عَنِ الْحَشَرَاتِ.","طق":"الطَّقُّ صَوْتٌ قَصِيرٌ كَضَرْبَةٍ خَفِيفَةٍ.","طب":"الطِّبُّ عِلْمُ تَشْخِيصِ الْأَمْرَاضِ وَعِلَاجِهَا.","بطح":"بَطَحَ الْوَلَدُ كُتُبَهُ عَلَى الطَّاوِلَةِ لِلْمُذَاكَرَةِ.","فطر":"فَطَرَ الصَّائِمُ عَلَى تَمْرٍ وَمَاءٍ.","شطر":"شَطَرَ الطَّبَّاخُ الدَّجَاجَةَ نِصْفَيْنِ.","وطأة":"وَطْأَةُ الْبَرْدِ شَدِيدَةٌ وَلَا بُدَّ مِنَ الدِّفْءِ.","رطل":"الرِّطْلُ وَزْنٌ قَدِيمٌ يُعَادِلُ نَحْوَ أَرْبَعِمِائَةِ غِرَامٍ.","وطس":"وَطَسَ الْحَصَانُ الْأَرْضَ بِحَوَافِرِهِ أَثْنَاءَ الْجَرْيِ.","سقط":"سَقَطَ الطِّفْلُ عَنِ الدَّرَّاجَةِ وَجُرِحَتْ رُكْبَتُهُ.","بسط":"بَسَطَ الرَّجُلُ السَّجَّادَةَ لِيُصَلِّيَ عَلَيْهَا.","نمط":"النَّمَطُ طَرِيقَةٌ ثَابِتَةٌ مُتَكَرِّرَةٌ.","ورط":"وَرَّطَ الصَّدِيقُ صَاحِبَهُ فِي مُشْكِلَةٍ.","سرط":"سَرَطَ الثُّعْبَانُ فَرِيسَتَهُ دُونَ مَضْغٍ.","طاحون":"الطَّاحُونُ مَبْنًى يُطْحَنُ فِيهِ الْقَمْحُ بِقُوَّةِ الرِّيحِ.","طوفان":"الطُّوفَانُ سَيْلٌ عَارِمٌ يَغْمُرُ الْأَرَاضِيَ.","طليعة":"الطَّلِيعَةُ أَوَائِلُ الْقَوْمِ فِي مُقَدِّمَةِ الصُّفُوفِ.","بطولة":"الْبُطُولَةُ شُجَاعَةٌ فِي مُوَاجَهَةِ الصِّعَابِ.","سطوة":"السَّطْوَةُ الْقُوَّةُ وَالسُّلْطَانُ الَّذِي يُخَافُ مِنْهُ.","مطبخ":"الْمَطْبَخُ غُرْفَةٌ يُعَدُّ فِيهَا الطَّعَامُ.","وطيس":"الْوَطِيسُ مَعْرَكَةٌ شَدِيدَةٌ.","رطوبة":"الرُّطُوبَةُ نِسْبَةُ الْبُخَارِ فِي الْهَوَاءِ.","وطواط":"الْوَطْوَاطُ طَائِرٌ لَيْلِيٌّ يَرَى بِالصَّوْتِ.","تساقط":"تَسَاقَطَتِ الثِّمَارُ النَّاضِجَةُ مِنَ الشَّجَرَةِ.","تبسط":"تَبَسَّطَ الضَّيْفُ فِي الْحَدِيثِ وَشَعَرَ بِالرَّاحَةِ.","تلبط":"تَلَبَّطَ الطِّفْلُ فِي الطِّينِ يَلْعَبُ بِلَا اكْتِرَاثٍ.","شريط":"الشَّرِيطُ قِطْعَةٌ ضَيِّقَةٌ مِنَ الْقُمَاشِ أَوِ الْوَرَقِ.","بسيط":"الْبَسِيطُ الشَّيْءُ السَّهْلُ الَّذِي لَا تَعْقِيدَ فِيهِ.","وسيط":"الْوَسِيطُ الشَّخْصُ الَّذِي يَتَوَسَّطُ بَيْنَ طَرَفَيْنِ.","طبيعية":"الطَّبِيعِيَّةُ انْتِمَاءُ الشَّيْءِ إِلَى طَبِيعَتِهِ.","طموحات":"الطُّمُوحَاتُ الْأَحْلَامُ الْكَبِيرَةُ الَّتِي نَسْعَى إِلَيْهَا.","طواحين":"الطَّوَاحِينُ مَبَانٍ تَطْحَنُ الْحُبُوبَ بِقُوَّةِ الرِّيحِ.","تطوير":"التَّطْوِيرُ الْعَمَلُ عَلَى تَحْسِينِ الشَّيْءِ.","تطبيق":"التَّطْبِيقُ تَنْفِيذُ الْفِكْرَةِ عَلَى أَرْضِ الْوَاقِعِ.","مطلوب":"الْمَطْلُوبُ الشَّيْءُ الَّذِي يُرَادُ وُجُودُهُ.","رطانة":"الرَّطَانَةُ الْكَلَامُ بِلُغَةٍ لَا يَفْهَمُهَا الْمُخَاطَبُ.","وطنية":"الْوَطَنِيَّةُ حُبُّ الْوَطَنِ وَالْإِخْلَاصُ لَهُ.","رطيب":"الرَّطِيبُ الشَّيْءُ النَّاعِمُ الطَّرِيُّ الَّذِي لَمْ يَجِفَّ.","انضبط":"اِنْضَبَطَ الطُّلَّابُ حِينَ دَخَلَ الْمُعَلِّمُ.","استنبط":"اِسْتَنْبَطَ الْعَالِمُ نَظَرِيَّةً مِنَ التَّجَارِبِ.","انضغط":"اِنْضَغَطَ الْهَوَاءُ دَاخِلَ الْبَالُونِ.","اشتراط":"الِاشْتِرَاطُ وَضْعُ شُرُوطٍ قَبْلَ الْمُوَافَقَةِ.","إفراط":"الْإِفْرَاطُ تَجَاوُزُ الْحَدِّ الْمَعْقُولِ.","انبساط":"الِانْبِسَاطُ الشُّعُورُ بِالرَّاحَةِ مَعَ الْأَصْدِقَاءِ.","ظن":"الظَّنُّ التَّفْكِيرُ فِي أَمْرٍ دُونَ يَقِينٍ تَامٍّ.","ظهر":"الظَّهْرُ الْجُزْءُ الْخَلْفِيُّ مِنَ الْجِسْمِ.","نظم":"نَظَمَ الشَّاعِرُ أَبْيَاتًا جَمِيلَةً عَنِ الطَّبِيعَةِ.","حظي":"حَظِيَ الطَّالِبُ الْمُجْتَهِدُ بِإِعْجَابِ زُمَلَائِهِ.","لظى":"لَظَى نَارٌ مُتَأَجِّجَةٌ شَدِيدَةُ الِاشْتِعَالِ.","وظف":"وَظَّفَ الْمُدِيرُ مُوَظَّفًا جَدِيدًا.","أظل":"أَظَلَّتِ الْغُيُومُ السَّمَاءَ مُنْذِرَةً بِالْمَطَرِ.","أظلم":"أَظْلَمَتِ السَّمَاءُ فَجْأَةً وَانْقَطَعَ النُّورُ.","نفظ":"نَفَظَ الرَّجُلُ يُخْرِجُ زَفْرَاتِ هَوَاءٍ بَعْدَ التَّعَبِ.","غلظ":"غَلُظَ الرَّجُلُ فِي أُسْلُوبِهِ فَنَفَرَ مِنْهُ النَّاسُ.","وعظ":"وَعَظَ الشَّيْخُ النَّاسَ وَأَمَرَهُمْ بِالتَّقْوَى.","لحاظ":"اللَّحَاظُ طَرَفُ الْعَيْنِ الَّذِي يَلِي الْأُذُنَ.","شواظ":"الشُّوَاظُ لَهَبٌ مِنَ النَّارِ لَا دُخَانَ فِيهِ.","ألحاظ":"الْأَلْحَاظُ نَظَرَاتٌ مِنْ طَرْفِ الْعَيْنِ.","ظريف":"الظَّرِيفُ خَفِيفُ الرُّوحِ الَّذِي يُحِبُّهُ الْجَمِيعُ.","ظلام":"الظَّلَامُ غِيَابُ الضَّوْءِ وَتَرَاكُمُ الْعَتَمَةِ.","ظليم":"الظَّلِيمُ ذَكَرُ النَّعَامَةِ.","منظمة":"الْمُنَظَّمَةُ هَيْئَةٌ تَعْمَلُ وَفْقَ أَهْدَافٍ مُحَدَّدَةٍ.","لحظة":"اللَّحْظَةُ أَقْصَرُ وَحْدَةٍ مِنَ الزَّمَنِ.","وظيفة":"الْوَظِيفَةُ الْعَمَلُ الَّذِي يُؤَدِّيهِ الشَّخْصُ مُقَابِلَ رَاتِبٍ.","وظفه":"وَظَّفَهُ فِي مَنْصِبٍ يُنَاسِبُ كَفَاءَتَهُ.","تلفظ":"تَلَفَّظَ الطِّفْلُ بِكَلِمَةٍ نَابِيَةٍ فَعَاقَبَهُ وَالِدُهُ.","تحفظ":"تَحَفَّظَ الشَّاهِدُ وَلَمْ يُفْصِحْ عَنِ الْمَعْلُومَاتِ.","تغلظ":"تَغَلَّظَ فِي رَدِّهِ فَأَحْزَنَ مَنْ يُحَاوِرُهُ.","احتفاظ":"الِاحْتِفَاظُ الْحِرْصُ عَلَى عَدَمِ فَقْدَانِ الشَّيْءِ.","استيقاظ":"الِاسْتِيقَاظُ الصُّحُوَةُ مِنَ النَّوْمِ.","إيعاظ":"الْإِيعَاظُ تَذْكِيرُ النَّاسِ بِالْقِيَمِ الْحَسَنَةِ.","ظروف":"الظُّرُوفُ الْأَحْوَالُ الَّتِي تُحِيطُ بِالشَّخْصِ.","ظاهرة":"الظَّاهِرَةُ حَدَثٌ يُلَاحَظُ وَيُدْرَسُ.","ظلمات":"الظُّلُمَاتُ الظَّلَامُ الشَّدِيدُ.","منظومة":"الْمَنْظُومَةُ مَجْمُوعَةٌ مُتَرَابِطَةٌ.","مظلوم":"الْمَظْلُومُ مَنْ وَقَعَ عَلَيْهِ الْجَوْرُ.","ملحوظة":"الْمَلْحُوظَةُ تَعْلِيقٌ يُشِيرُ إِلَى أَمْرٍ يَسْتَحِقُّ الِانْتِبَاهَ.","وظيفية":"الْوَظِيفِيَّةُ تَتَعَلَّقُ بِمَهَامِّ الْوَظِيفَةِ.","أظهرت":"أَظْهَرَتِ النَّتَائِجُ تَفَوُّقَ الطُّلَّابِ.","وظاهر":"وَظَاهَرَ الْحُلَفَاءُ بَعْضَهُمْ فِي مُوَاجَهَةِ الصُّعُوبَاتِ.","توعظ":"تَوَعَّظَ الْإِنْسَانُ مِنْ أَخْطَائِهِ.","تواعظ":"تَوَاعَظَ الْأَصْدِقَاءُ وَتَبَادَلُوا النُّصْحَ.","احتفظ":"اِحْتَفَظَ بِهَدِيَّةٍ تُذَكِّرُهُ بِجَدِّهِ.","استغلاظ":"الِاسْتِغْلَاظُ اعْتِبَارُ الشَّيْءِ فَاحِشًا.","استحفاظ":"الِاسْتِحْفَاظُ طَلَبُ الْحِفَاظِ عَلَى الشَّيْءِ.","استيعاظ":"الِاسْتِيعَاظُ طَلَبُ الِاتِّعَاظِ بِتَجَارِبِ الْآخَرِينَ.","عد":"الْعَدُّ إِحْصَاءُ الْأَشْيَاءِ لِمَعْرِفَةِ عَدَدِهَا.","عز":"الْعِزُّ الشَّرَفُ وَالرِّفْعَةُ بَيْنَ النَّاسِ.","نعل":"النَّعْلُ حِذَاءٌ خَفِيفٌ يَقِي الْقَدَمَ.","بعد":"الْبُعْدُ الْمَسَافَةُ الْفَاصِلَةُ بَيْنَ مَكَانَيْنِ.","تعب":"تَعِبَ الرَّاكِضُ فَجَلَسَ يَسْتَرِيحُ.","رعى":"رَعَى الرَّاعِي أَغْنَامَهُ فِي الْمَرَاعِي الْخَضْرَاءِ.","وعك":"وَعَكَهُ الْمَرَضُ فَلَزِمَ الْفِرَاشَ.","نفع":"نَفَعَ الْعِلْمُ أَصْحَابَهُ وَنَفَعَ مُجْتَمَعَهُمْ.","طبع":"طَبَعَ الْوَلَدُ رِسَالَتَهُ ثُمَّ أَرْسَلَهَا.","شفع":"شَفَعَ الْمَسْؤُولُ لِصَدِيقِهِ فَنَجَحَ.","جرع":"جَرَعَ الطِّفْلُ الدَّوَاءَ بِشَجَاعَةٍ.","فزع":"فَزَعَ الطِّفْلُ مِنَ الرَّعْدِ وَلَجَأَ إِلَى أُمِّهِ.","ورع":"الْوَرَعُ التَّقْوَى وَالِابْتِعَادُ عَنِ الْمَحَرَّمَاتِ.","عصفور":"الْعُصْفُورُ طَائِرٌ صَغِيرٌ يُغَرِّدُ فِي الصَّبَاحِ.","عجينة":"الْعَجِينَةُ مَزِيجٌ مِنَ الدَّقِيقِ وَالْمَاءِ.","عنوان":"الْعُنْوَانُ اسْمُ الْمَكَانِ الَّذِي تُرِيدُ إِرْسَالَ رِسَالَةٍ إِلَيْهِ.","تعليم":"التَّعْلِيمُ نَقْلُ الْمَعْرِفَةِ مِنَ الْمُعَلِّمِ إِلَى الطَّالِبِ.","مفعول":"الْمَفْعُولُ مَنْ وَقَعَ عَلَيْهِ الْفِعْلُ.","تعديل":"التَّعْدِيلُ تَغْيِيرٌ جُزْئِيٌّ لِلتَّحْسِينِ.","وعاء":"الْوِعَاءُ إِنَاءٌ يُحْفَظُ فِيهِ الطَّعَامُ.","رعاية":"الرِّعَايَةُ الِاهْتِمَامُ بِالشَّخْصِ وَالْحِفَاظُ عَلَيْهِ.","زعامة":"الزَّعَامَةُ الْقِيَادَةُ عَلَى جَمَاعَةٍ.","تجمع":"تَجَمَّعَ النَّاسُ لِلِاحْتِفَالِ.","تقطع":"تَقَطَّعَتِ الْعَلَاقَاتُ بَعْدَ خِلَافٍ.","تصنع":"تَصَنَّعَ السَّعَادَةَ رَغْمَ حُزْنِهِ.","تنويع":"التَّنْوِيعُ إِضَافَةُ تَغَيُّرَاتٍ لِتَجَنُّبِ الرَّتَابَةِ.","توزيع":"التَّوْزِيعُ قِسْمَةُ الشَّيْءِ بِعَدَالَةٍ.","عبقرية":"الْعَبْقَرِيَّةُ مَوْهِبَةٌ خَارِقَةٌ نَادِرَةٌ.","عدالة":"الْعَدَالَةُ إِعْطَاءُ كُلِّ ذِي حَقٍّ حَقَّهُ.","عملية":"الْعَمَلِيَّةُ تَدَخُّلٌ جِرَاحِيٌّ يَقُومُ بِهِ الطَّبِيبُ.","تعاون":"التَّعَاوُنُ الْعَمَلُ مَعًا لِتَحْقِيقِ هَدَفٍ مُشْتَرَكٍ.","متعلم":"الْمُتَعَلِّمُ مَنْ يَسْعَى دَائِمًا لِاكْتِسَابِ الْمَعْرِفَةِ.","تعطيل":"التَّعْطِيلُ وَقْفُ سَيْرِ الْعَمَلِ.","وعورة":"الْوُعُورَةُ صِفَةُ الطَّرِيقِ الصَّعْبِ.","رعاشة":"الرَّعَاشَةُ اضْطِرَابُ حَرَكَاتِ الْجِسْمِ.","زعزعة":"الزَّعْزَعَةُ التَّحْرِيكُ بِقُوَّةٍ حَتَّى يَفْقِدَ الثَّبَاتَ.","انتفع":"اِنْتَفَعَ الطَّالِبُ مِنَ الدَّرْسِ.","استمع":"اِسْتَمَعَ الطِّفْلُ بِانْتِبَاهٍ إِلَى الْقِصَّةِ.","تربع":"تَرَبَّعَ الشَّيْخُ وَرَاحَ يُحَدِّثُ أَحْفَادَهُ.","يراع":"الْيَرَاعُ قَصَبٌ صَنَعَ مِنْهُ الْعَرَبُ الْأَقْلَامَ.","ذراع":"الذِّرَاعُ الْجُزْءُ مِنَ الْيَدِ بَيْنَ الرُّسْغِ وَالْمِرْفَقِ.","وزاع":"الْوِزَاعُ مَا يَكُفُّ النَّفْسَ عَنِ الشَّرِّ.","غل":"الْغِلُّ الْحِقْدُ الْمَخْفِيُّ فِي الصَّدْرِ.","غص":"غَصَّ الطِّفْلُ بِقِطْعَةٍ مِنَ الطَّعَامِ.","غد":"غَدٌ يَوْمٌ جَدِيدٌ يَحْمِلُ فُرَصًا جَدِيدَةً.","سغب":"السَّغَبُ الْجُوعُ الشَّدِيدُ الَّذِي يُضْعِفُ الْجِسْمَ.","نغم":"النَّغَمُ صَوْتٌ مُوسِيقِيٌّ يُبْهِجُ الرُّوحَ.","بغى":"بَغَى الظَّالِمُ وَلَمْ يَنَلْ إِلَّا الْخِزْيَ.","وغر":"الْوَغَرُ حِقْدٌ مَخْزُونٌ يُجَاهِدُ الْعَاقِلُ عَلَى إِزَالَتِهِ.","رغد":"الرَّغَدُ الرَّخَاءُ وَسَعَةُ الْعَيْشِ.","وغل":"وَغَلَ الدَّخِيلُ بَيْنَ الْقَوْمِ.","نبغ":"نَبَغَ الطَّالِبُ فِي الرِّيَاضِيَّاتِ.","ثلغ":"ثَلَغَ رَأْسَهُ بِالْجِدَارِ غَضَبًا.","فلغ":"فَلَغَ النَّجَّارُ الْخَشَبَةَ إِلَى نِصْفَيْنِ.","زاغ":"زَاغَ عَنِ الطَّرِيقِ الصَّحِيحَةِ.","راغ":"رَاغَ الثَّعْلَبُ هَرَبًا مِنَ الصَّيَّادِ.","نزغ":"نَزَغَ الشَّيْطَانُ بَيْنَ الصَّدِيقَيْنِ.","غيمة":"الْغَيْمَةُ كُتْلَةٌ مِنَ الْبُخَارِ تَحْجُبُ الشَّمْسَ.","غاية":"الْغَايَةُ الْهَدَفُ الْأَسْمَى الَّذِي يَسْعَى إِلَيْهِ الْإِنْسَانُ.","غارة":"الْغَارَةُ هُجُومٌ مُفَاجِئٌ سَرِيعٌ.","مغامر":"الْمُغَامِرُ مَنْ يُحِبُّ الِاكْتِشَافَ وَاقْتِحَامَ الْمَجَاهِيلِ.","صغيرة":"الصَّغِيرَةُ شَيْءٌ قَلِيلُ الْحَجْمِ.","تغيير":"التَّغْيِيرُ الِانْتِقَالُ مِنْ حَالٍ إِلَى آخَرَ.","وغول":"الْوَغُولُ الدَّخِيلُ الَّذِي يَدُسُّ نَفْسَهُ.","رغيف":"الرَّغِيفُ قِطْعَةٌ مِنَ الْخُبْزِ لِشَخْصٍ وَاحِدٍ.","زغرودة":"الزَّغْرُودَةُ صَوْتٌ طَرِبٌ يُصْدَرُ فَرَحًا.","تصبغ":"تَصَبَّغَ شَعْرُهُ فَبَدَا أَصْغَرَ سِنًّا.","اندمغ":"اِنْدَمَغَ فِي الْمُنَظَّمَةِ وَجَمَعَ مَعْلُومَاتٍ.","ابتلغ":"اِبْتَلَغَ الْأَذَى وَتَحَمَّلَهُ.","تبليغ":"التَّبْلِيغُ إِيصَالُ الرِّسَالَةِ إِلَى مَنْ يَعْنِيهِمُ الْأَمْرُ.","تفريغ":"التَّفْرِيغُ إِخْرَاجُ مَا بِدَاخِلِ الشَّيْءِ.","أبلاغ":"الْأَبْلَاغُ الرَّسَائِلُ الرَّسْمِيَّةُ.","غيبوبة":"الْغَيْبُوبَةُ فَقْدَانُ الْوَعْيِ التَّامُّ.","غيرة":"الْغَيْرَةُ ضِيقٌ حِينَ يَنَالُ غَيْرُكَ مَا لَا تَنَالُهُ.","غريزة":"الْغَرِيزَةُ دَافِعٌ فِطْرِيٌّ بِلَا تَفْكِيرٍ.","تغلغل":"تَغَلْغَلَ النَّشِيدُ فِي قُلُوبِ الْمُسْتَمِعِينَ.","مغالطة":"الْمُغَالَطَةُ حُجَجٌ خَاطِئَةٌ تَبْدُو صَحِيحَةً.","مغرب":"الْمَغْرِبُ الِاتِّجَاهُ الَّذِي تَغِيبُ فِيهِ الشَّمْسُ.","رغبات":"الرَّغَبَاتُ الْأَشْيَاءُ الَّتِي يَتَمَنَّى الْإِنْسَانُ الْحُصُولَ عَلَيْهَا.","زغردة":"الزَّغْرَدَةُ أَصْوَاتُ الْفَرَحِ فِي الْمُنَاسَبَاتِ.","انطبغ":"اِنْطَبَغَ الثَّوْبُ بَعْدَ نَقْعِهِ فِي الصِّبَاغِ.","انصبغ":"اِنْصَبَغَ الشَّعْرُ بِالْحِنَّاءِ.","استصبغ":"اِسْتَصْبَغَ النَّسِيجُ بَعْدَ غَمْسِهِ فِي الصِّبَاغِ.","إبلاغ":"الْإِبْلَاغُ إِيصَالُ خَبَرٍ لِجِهَةٍ مُعَيَّنَةٍ.","دماغ":"الدِّمَاغُ الْعُضْوُ الَّذِي يَتَحَكَّمُ فِي الْجِسْمِ.","فم":"الْفَمُ فُتْحَةُ الرَّأْسِ نَأْكُلُ وَنَتَكَلَّمُ بِهَا.","فن":"الْفَنُّ مَوْهِبَةُ التَّعْبِيرِ عَنِ الْجَمَالِ.","فج":"الْفَجُّ طَرِيقٌ وَاسِعٌ بَيْنَ الْجِبَالِ.","نفر":"نَفَرَ الطَّيْرُ حِينَ سَمِعَ صَوْتًا مُفَاجِئًا.","صفق":"صَفَّقَ الْجُمْهُورُ إِعْجَابًا بِالْأَدَاءِ.","شفط":"شَفَطَ الطِّفْلُ عَصِيرَهُ بِالْمِصَاصَةِ.","وفى":"وَفَى بِوَعْدِهِ وَلَمْ يُخْلِفْهُ.","رفث":"الرَّفَثُ الْكَلَامُ الْفَاحِشُ الَّذِي يُتَجَنَّبُ.","ذفر":"الذَّفَرُ رَائِحَةٌ كَرِيهَةٌ.","نقف":"نَقَفَ الطَّائِرُ الْبَيْضَةَ بِمِنْقَارِهِ.","ثقف":"ثَقِفَ مَعَارِفَ عَدِيدَةً وَصَارَ مَرْجِعًا.","زرف":"زَرَفَ الصِّنْبُورُ الْمَاءَ بِغَزَارَةٍ.","جرف":"جَرَفَتِ الْفَيَضَانَاتُ التُّرَابَ.","ذرف":"ذَرَفَتِ الْأُمُّ الدُّمُوعَ حِينَ رَأَتْ وَلَدَهَا.","فهرس":"الْفَهْرَسُ قَائِمَةٌ بِمَحْتَوَيَاتِ الْكِتَابِ.","فلفل":"الْفُلْفُلُ بَهَارٌ حَادٌّ يُضَافُ لِلطَّعَامِ.","فانوس":"الْفَانُوسُ مِصْبَاحٌ قَدِيمٌ يُحْمَلُ بِالْيَدِ.","صفحة":"الصَّفْحَةُ وَجْهٌ وَاحِدٌ مِنَ الْوَرَقَةِ.","شفرة":"الشَّفْرَةُ الْجُزْءُ الْحَادُّ مِنَ السِّكِّينِ.","وفاء":"الْوَفَاءُ الِالْتِزَامُ بِالْعَهْدِ.","رفاهية":"الرَّفَاهِيَةُ الْحَيَاةُ الْمُرِيحَةُ.","زفاف":"الزِّفَافُ حَفْلَةُ الزَّوَاجِ.","تشغف":"تَشَغَّفَ بِالطَّبِيعَةِ فَكَتَبَ عَنْهَا.","تثقف":"تَثَقَّفَ بِالْقِرَاءَةِ فَنَضَجَتْ شَخْصِيَّتُهُ.","تكثف":"تَكَثَّفَ بُخَارُ الْمَاءِ عَلَى الزُّجَاجِ الْبَارِدِ.","شريف":"الشَّرِيفُ مَنِ اتَّصَفَ بِالنَّبَالَةِ.","زخرف":"الزَّخْرَفُ التَّزْيِينُ بِالنُّقُوشِ الْجَمِيلَةِ.","فلسفة":"الْفَلْسَفَةُ عِلْمُ الْبَحْثِ فِي مَعْنَى الْوُجُودِ.","فضاء":"الْفَضَاءُ الْمَكَانُ الَّذِي تَسْبَحُ فِيهِ النُّجُومُ.","فيروز":"الْفَيْرُوزُ حَجَرٌ كَرِيمٌ أَزْرَقُ يُصْنَعُ مِنْهُ الْحُلِيُّ.","تفكيك":"التَّفْكِيكُ فَصْلُ أَجْزَاءِ الشَّيْءِ لِفَهْمِهِ.","مفاهيم":"الْمَفَاهِيمُ الْأَفْكَارُ الَّتِي تَتَعَلَّقُ بِمَوْضُوعٍ مَا.","تفاصيل":"التَّفَاصِيلُ الْأَجْزَاءُ الدَّقِيقَةُ.","وفرة":"الْوَفْرَةُ الْكَثْرَةُ وَالزِّيَادَةُ عَنِ الْحَاجَةِ.","رفاهة":"الرَّفَاهَةُ النَّعِيمُ وَسَعَةُ الرِّزْقِ.","وفيرة":"الْوَفِيرَةُ الْكَمِيَّةُ الزَّائِدَةُ عَنِ الْحَاجَةِ.","استشف":"اِسْتَشَفَّ الرَّجُلُ نِيَّةَ الْآخَرِ مِنْ كَلَامِهِ.","انكشف":"اِنْكَشَفَ الْأَمْرُ وَظَهَرَتِ الْحَقِيقَةُ.","اكتشف":"اِكْتَشَفَ الْعُلَمَاءُ قَارَّةً جَدِيدَةً.","أشراف":"الْأَشْرَافُ ذَوُو الْمَكَانَةِ الرَّفِيعَةِ.","إسراف":"الْإِسْرَافُ الزِّيَادَةُ عَنِ الْحَدِّ فِي الِاسْتِهْلَاكِ.","إتراف":"الْإِتْرَافُ التَّنَعُّمُ الزَّائِدُ وَالتَّرَفُّهُ الْمُفْرِطُ.","قف":"الْقِفُّ الْأَرْضُ الصُّلْبَةُ الْمُرْتَفِعَةُ.","قص":"الْقَصُّ هُوَ عَظْمَةُ الصَّدْرِ.","قد":"الْقِدُّ الْجِلْدُ الَّذِي يُشَقُّ إِلَى قِطَعٍ.","نقر":"نَقَرَ الطَّائِرُ الْخَشَبَةَ بِمِنْقَارِهِ.","بقر":"بَقَرَ الْجَرَّاحُ الْجُرْحَ لِتَنْظِيفِهِ.","فقر":"الْفَقْرُ الْحَاجَةُ وَقِلَّةُ الْمَالِ.","وقع":"وَقَعَ الْكِتَابُ مِنَ الرَّفِّ.","رقد":"رَقَدَ الطِّفْلُ مُبَكِّرًا بَعْدَ يَوْمٍ مُتْعِبٍ.","وقف":"وَقَفَ الرَّجُلُ أَمَامَ الْبَابِ يَنْتَظِرُ.","نطق":"نَطَقَ الطِّفْلُ كَلِمَتَهُ الْأُولَى فَفَرِحَتِ الْأُمُّ.","نسق":"نَسَّقَ الْمُنَظِّمُ الْأَثَاثَ بِطَرِيقَةٍ جَمِيلَةٍ.","شقق":"شَقَّقَ الرَّجُلُ الْخَشَبَ لِإِشْعَالِ النَّارِ.","فرق":"فَرَّقَ الْأَبُ بَيْنَ أَوْلَادِهِ بِالْعَدَالَةِ.","أرق":"الْأَرَقُ عَدَمُ الْقُدْرَةِ عَلَى النَّوْمِ.","زوق":"زَوَّقَ النَّجَّارُ الْأَثَاثَ فَصَارَ جَمِيلًا.","قانون":"الْقَانُونُ مَجْمُوعَةُ الْقَوَاعِدِ الَّتِي تُنَظِّمُ الْمُجْتَمَعَ.","قصيدة":"الْقَصِيدَةُ نَصٌّ شِعْرِيٌّ مُوزُونٌ وَمُقَفًّى.","قافلة":"الْقَافِلَةُ مَجْمُوعَةُ مَطَايَا تَسِيرُ مَعًا فِي الصَّحْرَاءِ.","تقدير":"التَّقْدِيرُ الِاحْتِرَامُ وَالتَّعْظِيمُ لِلشَّخْصِ.","نقيصة":"النَّقِيصَةُ الْعَيْبُ الَّذِي يُنْقِصُ مِنْ قَدْرِ الشَّخْصِ.","بقلاوة":"الْبَقْلَاوَةُ حَلَوَى شَرْقِيَّةٌ لَذِيذَةٌ.","وقاحة":"الْوَقَاحَةُ عَدَمُ الْحَيَاءِ.","رقابة":"الرَّقَابَةُ الْمُرَاقَبَةُ وَالِاطِّلَاعُ عَلَى الْأُمُورِ.","وقاية":"الْوِقَايَةُ الْحِمَايَةُ مِنَ الْأَذَى.","تعلق":"تَعَلَّقَ الطِّفْلُ بِلُعْبَتِهِ الْمُفَضَّلَةِ.","تألق":"تَأَلَّقَ الطَّالِبُ فِي الِامْتِحَانِ.","تدفق":"تَدَفَّقَ الْمَاءُ مِنَ الصِّنْبُورِ بِقُوَّةٍ.","تذوق":"تَذَوَّقَ الطِّفْلُ الْحَلْوَى بِبُطْءٍ.","تشوق":"تَشَوَّقَ إِلَى رُؤْيَةِ وَالِدَيْهِ.","أسواق":"الْأَسْوَاقُ أَمَاكِنُ الْبَيْعِ وَالشِّرَاءِ.","قضاء":"الْقَضَاءُ الْحُكْمُ بَيْنَ النَّاسِ بِالْعَدْلِ.","قرآن":"الْقُرْآنُ كِتَابُ اللهِ الْمُنَزَّلُ عَلَى النَّبِيِّ.","قيمة":"الْقِيمَةُ الثَّمَنُ الَّذِي يُقَدَّرُ بِهِ الشَّيْءُ.","تقنية":"التِّقْنِيَّةُ تَطْبِيقُ الْعِلْمِ لِحَلِّ الْمَشَاكِلِ.","مقياس":"الْمِقْيَاسُ أَدَاةٌ لِتَحْدِيدِ الْكَمِّيَّاتِ.","تقارب":"التَّقَارُبُ الِاقْتِرَابُ وَتَضْيِيقُ الْمَسَافَةِ.","وقود":"الْوَقُودُ مَادَّةٌ تُحْرَقُ لِإِنْتَاجِ الطَّاقَةِ.","أقام":"أَقَامَ الرَّجُلُ فِي الْمَدِينَةِ سَنَوَاتٍ.","رقيب":"الرَّقِيبُ مَنْ يُرَاقِبُ وَيُحَافِظُ.","انطلق":"اِنْطَلَقَ الرِّيَاضِيُّ نَحْوَ الْهَدَفِ.","استحق":"اِسْتَحَقَّ الطَّالِبُ الْجَائِزَةَ.","تعمق":"تَعَمَّقَ فِي دِرَاسَةِ الْمَوْضُوعِ.","أذواق":"الْأَذْوَاقُ تَفَضِيلَاتٌ تَخْتَلِفُ مِنْ شَخْصٍ لِآخَرَ.","إشراق":"الْإِشْرَاقُ بُزُوغُ نُورِ الشَّمْسِ.","انطلاق":"الِانْطِلَاقُ الْبَدَاءُ بِحَمَاسٍ وَقُوَّةٍ.","كف":"الْكَفُّ رَاحَةُ الْيَدِ.","كم":"الْكُمُّ جُزْءُ الثَّوْبِ الَّذِي يُغَطِّي الذِّرَاعَ.","كن":"الْكُنُّ الْمَكَانُ الَّذِي يَسْتَظِلُّ فِيهِ الشَّخْصُ.","بكر":"بَكَّرَ الطَّالِبُ إِلَى الْمَدْرَسَةِ قَبْلَ غَيْرِهِ.","سكب":"سَكَبَ الْوَلَدُ الْمَاءَ فِي الْكُوبِ.","نكت":"نَكَتَ الرَّجُلُ بِعُودٍ عَلَى الْأَرْضِ.","وكل":"وَكَّلَ الرَّجُلُ أَمْرَهُ إِلَى اللهِ.","ركز":"رَكَّزَ الطَّالِبُ انْتِبَاهَهُ أَثْنَاءَ الدَّرْسِ.","وكز":"وَكَزَهُ بِمِرْفَقِهِ تَنْبِيهًا.","هلك":"هَلَكَ الظَّالِمُ وَبَقِيَ الْعَدْلُ.","نهك":"نَهَكَهُ الْمَرَضُ فَأَنْهَكَ طَاقَتَهُ.","سلك":"سَلَكَ الطَّالِبُ طَرِيقَ الصِّدْقِ وَالِاجْتِهَادِ.","درك":"الدَّرَكُ طَبَقَةٌ سُفْلَى.","فرك":"فَرَكَ الطِّفْلُ عَيْنَيْهِ بَعْدَ الِاسْتِيقَاظِ.","حرك":"حَرَّكَ الطَّبَّاخُ الطَّعَامَ بِالْمِلْعَقَةِ.","كرنب":"الْكُرُنْبُ خَضْرَوَاتٌ وَرَقِيَّةٌ غَنِيَّةٌ بِالْفِيتَامِينَاتِ.","كاكاو":"الْكَاكَاوُ ثَمَرَةٌ تُصْنَعُ مِنْهَا الشُّوكُولَاتَةُ.","كنغر":"الْكَنْغَرُ حَيَوَانٌ أُسْتِرَالِيٌّ يَحْمِلُ صَغِيرَهُ فِي جِرَابِهِ.","تكريم":"التَّكْرِيمُ تَشْرِيفُ الشَّخْصِ تَقْدِيرًا لِإِنْجَازَاتِهِ.","شكيمة":"الشَّكِيمَةُ الشِّدَّةُ وَالْحَزْمُ فِي الشَّخْصِيَّةِ.","مكانة":"الْمَكَانَةُ الْمَرْتَبَةُ وَالْمَكَانَةُ بَيْنَ النَّاسِ.","وكالة":"الْوَكَالَةُ تَفْوِيضُ شَخْصٍ لِلتَّصَرُّفِ نِيَابَةً.","ركيزة":"الرَّكِيزَةُ الْأَسَاسُ الْقَوِيُّ الَّذِي يَقُومُ عَلَيْهِ الشَّيْءُ.","وكيل":"الْوَكِيلُ مَنْ يُفَوَّضُ لِتَمْثِيلِ غَيْرِهِ.","تملك":"تَمَلَّكَ الْعِلْمُ قَلْبَهُ.","تهالك":"تَهَالَكَ عَلَى النَّوْمِ بَعْدَ تَعَبٍ شَدِيدٍ.","تشابك":"تَشَابَكَتِ الْأَفْكَارُ فِي ذِهْنِهِ.","أسماك":"الْأَسْمَاكُ مَخْلُوقَاتٌ تَعِيشُ فِي الْمَاءِ.","أفلاك":"الْأَفْلَاكُ الْمَدَارَاتُ الَّتِي تَدُورُ فِيهَا الْكَوَاكِبُ.","إدراك":"الْإِدْرَاكُ الْفَهْمُ الْعَمِيقُ لِلْأُمُورِ.","كرامة":"الْكَرَامَةُ الشَّرَفُ وَالاحْتِرَامُ الذَّاتِيُّ.","كفاءة":"الْكَفَاءَةُ الْقُدْرَةُ عَلَى أَدَاءِ الْعَمَلِ بِجَوْدَةٍ.","تكامل":"التَّكَامُلُ تَرَابُطُ الْأَجْزَاءِ لِتَشْكِيلِ كُلٍّ مُتَكَامِلٍ.","تكاثر":"التَّكَاثُرُ الزِّيَادَةُ فِي الْعَدَدِ.","وكالات":"الْوَكَالَاتُ الْمَكَاتِبُ الَّتِي تَتَوَلَّى الْأَعْمَالَ نِيَابَةً.","ركاز":"الرِّكَازُ الْمَعَادِنُ الْمَدْفُونَةُ فِي الْأَرْضِ.","وكلاء":"الْوُكَلَاءُ جَمْعُ وَكِيلٍ.","استمسك":"اِسْتَمْسَكَ بِرَأْيِهِ وَلَمْ يَتَرَاجَعْ.","انفك":"اِنْفَكَّ الْقَيْدُ وَأُطْلِقَ سَرَاحُهُ.","تمالك":"تَمَالَكَ نَفْسَهُ وَلَمْ يُبْدِ ضَعْفَهُ.","اشتراك":"الِاشْتِرَاكُ الِانْضِمَامُ إِلَى مَجْمُوعَةٍ.","ارتباك":"الِارْتِبَاكُ الِاضْطِرَابُ وَالتَّشَوُّشُ.","استدراك":"الِاسْتِدْرَاكُ تَصْحِيحُ خَطَأٍ أَوِ اسْتِكْمَالُ نَقْصٍ.","ارتبك":"اِرْتَبَكَ الطَّالِبُ أَمَامَ الْجُمْهُورِ.","لب":"اللُّبُّ جَوْهَرُ الشَّيْءِ وَخَالِصُهُ.","لز":"اللَّزُّ الْإِلْصَاقُ الشَّدِيدُ.","لج":"لَجَّ الرَّجُلُ فِي رَأْيِهِ وَلَمْ يَتَرَاجَعْ.","بلع":"بَلَعَ الطِّفْلُ الدَّوَاءَ بِسُرْعَةٍ.","سلق":"سَلَقَتِ الْأُمُّ الْبَيْضَ فِي الْمَاءِ الْمَغْلِيِّ.","بلط":"بَلَّطَ الْبَنَّاءُ أَرْضِيَّةَ الْغُرْفَةِ.","ولج":"وَلَجَ الضَّيْفُ إِلَى الْبَيْتِ.","زلق":"زَلَقَ الْوَلَدُ عَلَى الْأَرْضِ الْمَبْلُولَةِ.","ألق":"الْأَلَقُ الْبَرِيقُ وَاللَّمَعَانُ الْجَمِيلُ.","نمل":"النَّمْلُ حَشَرَةٌ صَغِيرَةٌ مُثَابِرَةٌ.","أكل":"أَكَلَ الطِّفْلُ وَجْبَتَهُ كَامِلَةً.","شغل":"شَغَلَ الْوَلَدُ وَقْتَهُ بِالْقِرَاءَةِ.","جرل":"الْجَرَلُ حِجَارَةٌ صَغِيرَةٌ تَمْلَأُ الْوَادِيَ.","أزل":"الْأَزَلُ الزَّمَنُ الَّذِي لَا بِدَايَةَ لَهُ.","لوحة":"اللُّوحَةُ عَمَلٌ فَنِّيٌّ مَرْسُومٌ.","لاعب":"اللَّاعِبُ مَنْ يُشَارِكُ فِي رِيَاضَةٍ أَوْ لُعْبَةٍ.","لؤلؤ":"اللُّؤْلُؤُ جَوْهَرَةٌ بَيْضَاءُ تُوجَدُ دَاخِلَ الْمَحَارِ.","علامة":"الْعَلَامَةُ إِشَارَةٌ تَدُلُّ عَلَى شَيْءٍ.","ملصق":"الْمُلْصَقُ وَرَقَةٌ مُلَوَّنَةٌ تُلْصَقُ لِلْإِعْلَانِ.","ولاية":"الْوِلَايَةُ الْمَنْطِقَةُ الَّتِي يَحْكُمُهَا وَالٍ.","وليمة":"الْوَلِيمَةُ طَعَامٌ يُعَدُّ فِي الْمُنَاسَبَاتِ.","تجمل":"تَجَمَّلَ الشَّابُّ قَبْلَ الْخُرُوجِ.","تأمل":"تَأَمَّلَ الشَّاعِرُ مَنَاظِرَ الطَّبِيعَةِ.","تحمل":"تَحَمَّلَ الرَّجُلُ الصِّعَابَ بِصَبْرٍ.","أطفال":"الْأَطْفَالُ بَرَاعِمُ الْمُجْتَمَعِ.","أجيال":"الْأَجْيَالُ طَبَقَاتٌ مُتَعَاقِبَةٌ مِنَ النَّاسِ.","أبطال":"الْأَبْطَالُ مَنِ اتَّصَفُوا بِالشَّجَاعَةِ.","لغوية":"اللُّغَوِيَّةُ تَتَعَلَّقُ بِعِلْمِ اللُّغَةِ.","لسانية":"اللِّسَانِيَّةُ عِلْمٌ يَدْرُسُ اللُّغَةَ الْبَشَرِيَّةَ.","لطيفة":"اللَّطِيفَةُ حِكَايَةٌ طَرِيفَةٌ تُضْحِكُ.","معلمة":"الْمُعَلِّمَةُ مَنْ تَتَوَلَّى التَّدْرِيسَ.","مظلومة":"الْمَظْلُومَةُ مَنْ وَقَعَ عَلَيْهَا الظُّلْمُ.","زلازل":"الزَّلَازِلُ جَمْعُ زَلْزَالٍ.","ولوج":"الْوُلُوجُ الدُّخُولُ إِلَى مَكَانٍ.","ألمانية":"الْأَلْمَانِيَّةُ اللُّغَةُ الرَّسْمِيَّةُ لِأَلْمَانِيَا.","استقل":"اِسْتَقَلَّ الطَّالِبُ فِي رَأْيِهِ.","اشتغل":"اِشْتَغَلَ الرَّجُلُ بِتِجَارَةِ الْكُتُبِ.","تدخل":"تَدَخَّلَ الْمُعَلِّمُ لِحَلِّ النِّزَاعِ.","إرسال":"الْإِرْسَالُ إِيصَالُ شَيْءٍ إِلَى شَخْصٍ مُعَيَّنٍ.","اتصال":"الِاتِّصَالُ التَّوَاصُلُ بَيْنَ شَخْصَيْنِ.","استقلال":"الِاسْتِقْلَالُ التَّحَرُّرُ مِنَ التَّبَعِيَّةِ.","مد":"الْمَدُّ امْتِدَادُ الشَّيْءِ وَاتِّسَاعُهُ.","مر":"الْمُرُّ الشَّيْءُ ذُو الطَّعْمِ الْكَرِيهِ.","مج":"الْمَجُّ إِخْرَاجُ الطَّعَامِ مِنَ الْفَمِ.","شمع":"الشَّمَعُ مَادَّةٌ تُصْنَعُ مِنْهَا الشُّمُوعُ.","طمع":"طَمِعَ فِي مَا لَا يَسْتَحِقُّهُ.","أمل":"الْأَمَلُ تَوَقُّعُ حُدُوثِ خَيْرٍ.","زمر":"زَمَرَ الرَّاعِي عَلَى مِزْمَارِهِ فِي الْحَقْلِ.","لثم":"لَثَمَ الطِّفْلُ خَدَّ أُمِّهِ بِحُبٍّ.","صلم":"صَلَمَ الْجَزَّارُ قِطَعًا مِنَ اللَّحْمِ.","ثلم":"ثَلَمَ الصَّدَأُ حَافَّةَ السِّكِّينِ.","ورم":"الْوَرَمُ تَضَخُّمٌ فِي جُزْءٍ مِنَ الْجِسْمِ.","زحم":"زَحَمَتِ السَّيَّارَاتُ الطَّرِيقَ.","أدم":"الْأَدَمُ الْجِلْدُ الْمَدْبُوغُ الرَّفِيعُ.","مساء":"الْمَسَاءُ الْوَقْتُ بَيْنَ الظُّهْرِ وَالْغُرُوبِ.","مرآة":"الْمِرْآةُ سَطْحٌ يَعْكِسُ الصُّوَرَ.","منهج":"الْمَنْهَجُ الطَّرِيقَةُ الْمُنَظَّمَةُ لِلدِّرَاسَةِ.","شمعة":"الشَّمْعَةُ أَسْطُوَانَةٌ مِنَ الشَّمَعِ.","تمكين":"التَّمْكِينُ مَنْحُ الشَّخْصِ الْقُدْرَةَ عَلَى الْفِعْلِ.","نموذج":"النَّمُوذَجُ مِثَالٌ يُحْتَذَى بِهِ.","رمانة":"الرُّمَّانَةُ ثَمَرَةٌ حَمْرَاءُ لَذِيذَةٌ.","وميض":"الْوَمِيضُ بَرِيقٌ سَرِيعٌ مِنَ الضَّوْءِ.","أمانة":"الْأَمَانَةُ صِفَةُ الشَّخْصِ الثِّقَةِ.","تبسم":"تَبَسَّمَ الطِّفْلُ حِينَ رَأَى هَدِيَّتَهُ.","تألم":"تَأَلَّمَ مِنَ الْجُرْحِ.","انتقم":"اِنْتَقَمَ الْمَظْلُومُ لِنَفْسِهِ.","أرقام":"الْأَرْقَامُ رُمُوزٌ نُعَبِّرُ بِهَا عَنِ الْكَمِّيَّاتِ.","أقسام":"الْأَقْسَامُ الْأَجْزَاءُ الَّتِي يُقْسَمُ إِلَيْهَا الشَّيْءُ.","مصطلح":"الْمُصْطَلَحُ كَلِمَةٌ مُتَّفَقٌ عَلَيْهَا.","مسؤولية":"الْمَسْؤُولِيَّةُ الِالْتِزَامُ بِأَدَاءِ الْوَاجِبَاتِ.","تمدين":"التَّمْدِينُ إِدْخَالُ قِيَمِ الْمَدَنِيَّةِ.","تشميل":"التَّشْمِيلُ جَعْلُ الشَّيْءِ شَامِلًا.","تنمية":"التَّنْمِيَةُ تَطْوِيرُ الْقُدُرَاتِ.","رمزية":"الرَّمْزِيَّةُ التَّعْبِيرُ بِالرُّمُوزِ.","أمثلة":"الْأَمْثِلَةُ نَمَاذِجُ تُوضِّحُ الْمَعْنَى.","وميضات":"الْوَمِيضَاتُ بَرِيقَاتٌ مُتَكَرِّرَةٌ مِنَ الضَّوْءِ.","انتظم":"اِنْتَظَمَ فِي عَمَلِهِ.","انسجم":"اِنْسَجَمَ الْفَرِيقُ وَعَمِلَ بِتَنَاغُمٍ.","استفهم":"اِسْتَفْهَمَ عَنِ الطَّرِيقِ الصَّحِيحِ.","اهتمام":"الِاهْتِمَامُ التَّرْكِيزُ وَالِانْتِبَاهُ.","إلزام":"الْإِلْزَامُ إِيجَابُ الشَّيْءِ وَجَعْلُهُ لَازِمًا.","التزام":"الِالْتِزَامُ الْوَفَاءُ بِالتَّعَهُّدَاتِ.","نم":"النَّمُّ نَقْلُ الْكَلَامِ بَيْنَ النَّاسِ لِإِثَارَةِ الْفِتْنَةِ.","نق":"النَّقُّ صَوْتُ الضِّفْدَعَةِ عِنْدَ الْمَاءِ.","نك":"النَّكُّ الضَّرْبُ الْمُتَكَرِّرُ الْخَفِيفُ.","بنى":"بَنَى الْعُمَّالُ الْجِدَارَ بِسُرْعَةٍ.","سنح":"سَنَحَتِ الْفُرْصَةُ فَاغْتَنَمَهَا الْفَطِينُ.","صنع":"صَنَعَ الْوَلَدُ هَدِيَّةً بِيَدَيْهِ.","ونى":"وَنَى الرَّجُلُ فِي عَمَلِهِ بَعْدَ طُولِ التَّعَبِ.","رنا":"رَنَا الطِّفْلُ إِلَى السَّمَاءِ يَتَأَمَّلُ النُّجُومَ.","كمن":"كَمَنَ الْجُنْدِيُّ خَلْفَ الشَّجَرَةِ.","فتن":"فَتَنَ الشَّيْطَانُ كَثِيرِينَ بِالزِّينَةِ وَالشَّهَوَاتِ.","سكن":"سَكَنَ الطِّفْلُ بَعْدَ أَنْ طَمْأَنَتْهُ أُمُّهُ.","حزن":"الْحُزْنُ شُعُورٌ بِالْأَلَمِ النَّفْسِيِّ.","ودن":"وَدَنَ الزَّارِعُ الْأَرْضَ قَبْلَ الزِّرَاعَةِ.","نبيل":"النَّبِيلُ الشَّخْصُ ذُو الْأَخْلَاقِ الرَّفِيعَةِ.","عناية":"الْعِنَايَةُ الِاهْتِمَامُ وَالرِّعَايَةُ.","بنيان":"الْبُنْيَانُ الْبِنَاءُ الضَّخْمُ الْمُتَرَابِطُ.","رنين":"الرَّنِينُ صَوْتٌ مُتَرَدِّدٌ.","زينة":"الزِّينَةُ مَا يُزَيِّنُ الْمَكَانَ أَوِ الشَّخْصَ.","أنيس":"الْأَنِيسُ الصَّاحِبُ الْمُؤْنِسُ.","تمكن":"تَمَكَّنَ مِنِ اجْتِيَازِ الِامْتِحَانِ.","تأمن":"تَأَمَّنَ الشَّخْصُ حِينَ وَجَدَ مَنْ يُوَفِّرُ لَهُ الْأَمَانَ.","تضمن":"تَضَمَّنَ الْكِتَابُ مَعْلُومَاتٍ قَيِّمَةً.","ألوان":"الْأَلْوَانُ الْأَحْمَرُ وَالْأَزْرَقُ وَالْأَصْفَرُ وَغَيْرُهَا.","أزمان":"الْأَزْمَانُ الْحِقَبُ الزَّمَنِيَّةُ الْمُتَعَاقِبَةُ.","إتقان":"الْإِتْقَانُ أَدَاءُ الشَّيْءِ بِأَعْلَى جَوْدَةٍ.","نظرية":"النَّظَرِيَّةُ فِكْرَةٌ عِلْمِيَّةٌ تُفَسِّرُ ظَاهِرَةً مَا.","نفسية":"النَّفْسِيَّةُ تَتَعَلَّقُ بِالْعَقْلِ وَالْمَشَاعِرِ.","نباتية":"النَّبَاتِيَّةُ تَتَعَلَّقُ بِالنَّبَاتِ.","تنافس":"التَّنَافُسُ الْمُنَافَسَةُ بَيْنَ طَرَفَيْنِ.","تناغم":"التَّنَاغُمُ الِانْسِجَامُ وَالتَّوَافُقُ.","بناية":"الْبِنَايَةُ مَبْنًى كَبِيرٌ.","رنانة":"الرَّنَّانَةُ ذَاتُ الصَّوْتِ الرَّنَّانِ.","زنابق":"الزَّنَابِقُ زُهُورٌ جَمِيلَةٌ مُعَطَّرَةٌ.","أناشيد":"الْأَنَاشِيدُ أَغَانٍ جَمِيلَةٌ.","استكن":"اِسْتَكَنَّ فِي مَكَانِهِ مُسْتَتِرًا.","استوطن":"اِسْتَوْطَنَ الْمُهَاجِرُ مَدِينَةً جَدِيدَةً.","استحسن":"اِسْتَحْسَنَ الْجَمِيعُ الِاقْتِرَاحَ.","اتزان":"الِاتِّزَانُ التَّوَازُنُ بَيْنَ الْأُمُورِ.","إمعان":"الْإِمْعَانُ التَّعَمُّقُ فِي التَّفْكِيرِ.","إحسان":"الْإِحْسَانُ الْفِعْلُ الْجَيِّدُ الَّذِي يَنْفَعُ الْآخَرِينَ.","هم":"الْهَمُّ الْحُزْنُ وَالْقَلَقُ.","هب":"الْهَبُّ هُبُوبُ الرِّيحِ.","هر":"الْهِرُّ هُوَ الْقِطُّ.","بهج":"بَهَجَ الْحَدِيقَةَ فَصَارَتْ جَمِيلَةً.","سهر":"سَهِرَ الطَّالِبُ يُذَاكِرُ.","شهر":"شَهَرَ الرَّجُلُ سَيْفَهُ.","وهب":"وَهَبَ الرَّجُلُ مَالَهُ لِلْفُقَرَاءِ.","رهف":"رَهُفَ الشَّيْءُ حِينَ صَارَ دَقِيقًا.","نبه":"نَبَّهَ الصَّدِيقُ صَاحِبَهُ إِلَى الْخَطَأِ.","فقه":"فَقِهَ الطَّالِبُ مَعَانِيَ الدَّرْسِ.","سفه":"سَفِهَ مَنْ أَهْدَرَ وَقْتَهُ فِيمَا لَا يُفِيدُ.","فره":"الْفَرَهُ النَّشَاطُ وَالنَّضَارَةُ.","جاه":"الْجَاهُ الْمَكَانَةُ الرَّفِيعَةُ بَيْنَ النَّاسِ.","نزه":"نَزَهَ عَنِ الْخَطَأِ.","هواء":"الْهَوَاءُ الْغَازُ الَّذِي نَتَنَفَّسُهُ.","هوية":"الْهُوِيَّةُ مَجْمُوعُ الصِّفَاتِ الَّتِي تُعَرِّفُ شَخْصًا.","هداية":"الْهِدَايَةُ الدَّلَالَةُ إِلَى الطَّرِيقِ الصَّحِيحِ.","نهاية":"النِّهَايَةُ الْحَدُّ الْأَخِيرُ لِلشَّيْءِ.","تهنية":"التَّهْنِيَةُ التَّبْرِيكُ وَالتَّرْحِيبُ.","وهاج":"الْوَهَّاجُ الشَّيْءُ الَّذِي يُضِيءُ بِشِدَّةٍ.","زهاد":"الزُّهَّادُ مَنْ تَرَكُوا الدُّنْيَا زُهْدًا.","رهافة":"الرَّهَافَةُ الدِّقَّةُ وَالرَّقَّةُ فِي الشُّعُورِ.","تشابه":"تَشَابَهَ الْأَخَوَانِ فِي الشَّكْلِ.","تنبه":"تَنَبَّهَ لِلْخَطَأِ مُبَكِّرًا.","توجه":"تَوَجَّهَ نَحْوَ هَدَفِهِ بِثَبَاتٍ.","أوجه":"الْأَوْجُهُ جَمْعُ وَجْهٍ.","أشباه":"الْأَشْبَاهُ الْأَمْثَالُ وَالنَّظَائِرُ.","أبواه":"أَبَوَاهُ أَحَبُّ النَّاسِ إِلَيْهِ.","هندسة":"الْهَنْدَسَةُ عِلْمُ الْأَشْكَالِ وَالْمَسَاحَاتِ.","هاجس":"الْهَاجِسُ الْفِكْرُ الَّذِي يُسَيْطِرُ عَلَى الْعَقْلِ.","هجرة":"الْهِجْرَةُ الِانْتِقَالُ مِنْ مَكَانٍ إِلَى آخَرَ.","تنهيدة":"التَّنْهِيدَةُ زَفِيرٌ عَمِيقٌ يُعَبِّرُ عَنِ الضِّيقِ.","مشهدية":"الْمَشْهَدِيَّةُ الطَّابَعُ الْبَصَرِيُّ لِمَوْقِفٍ مَا.","نباهة":"النَّبَاهَةُ الذَّكَاءُ وَسُرْعَةُ الْفِطْنَةِ.","وهدة":"الْوَهْدَةُ حُفْرَةٌ فِي الْأَرْضِ.","رهبانية":"الرَّهْبَانِيَّةُ التَّفَرُّغُ لِلْعِبَادَةِ.","زهدية":"الزُّهْدِيَّةُ مَا يَتَعَلَّقُ بِالزُّهْدِ.","تفقه":"تَفَقَّهَ فِي الدِّينِ.","استنبه":"اِسْتَنْبَهَ الْحَارِسُ عِنْدَ صَوْتِ الطَّارِقِ.","استفقه":"اِسْتَفْقَهَ الطَّالِبُ مِنَ الشَّيْخِ.","انتباه":"الِانْتِبَاهُ التَّرْكِيزُ عَلَى الشَّيْءِ.","اتجاه":"الِاتِّجَاهُ الطَّرِيقُ أَوِ الْمِيلُ نَحْوَ شَيْءٍ.","إكراه":"الْإِكْرَاهُ إِجْبَارُ شَخْصٍ عَلَى شَيْءٍ.","يأس":"الْيَأْسُ فَقْدَانُ الْأَمَلِ.","يبس":"يَبِسَ الْعُشْبُ فِي الصَّيْفِ.","بيع":"الْبَيْعُ تَبَادُلُ الْبَضَائِعِ بِالْمَالِ.","شيخ":"الشَّيْخُ الرَّجُلُ الْكَبِيرُ فِي السِّنِّ وَالتَّجْرِبَةِ.","صيف":"الصَّيْفُ أَحَرُّ فُصُولِ السَّنَةِ.","ريح":"الرِّيحُ هَوَاءٌ يَتَحَرَّكُ.","أين":"أَيْنَ تَذْهَبُ؟","فتي":"الْفَتِيُّ الشَّابُّ النَّضِرُ.","صفي":"الصَّفِيُّ الصَّدِيقُ الْمُخْلِصُ.","شجي":"الشَّجِيُّ اللَّحْنُ الْمُؤَثِّرُ الْحَزِينُ.","ثري":"الثَّرِيُّ الشَّخْصُ الْغَنِيُّ.","وري":"الْوَرِيُّ النَّضِرُ الطَّرِيُّ.","جاري":"الْجَارِيُّ الشَّيْءُ الَّذِي يَسِيرُ حَالِيًّا.","يسار":"الْيَسَارُ الِاتِّجَاهُ الْمُقَابِلُ لِلْيَمِينِ.","يمين":"الْيَمِينُ الِاتِّجَاهُ الَّذِي يَكُونُ فِيهِ الْيَدُ الْيُمْنَى.","يقين":"الْيَقِينُ الْإِيمَانُ الرَّاسِخُ دُونَ شَكٍّ.","شياطين":"الشَّيَاطِينُ الْكَائِنَاتُ الشِّرِّيرَةُ.","تيسير":"التَّيْسِيرُ جَعْلُ الشَّيْءِ سَهْلًا.","بيطار":"الْبَيْطَارُ طَبِيبُ الْحَيَوَانَاتِ.","ريادة":"الرِّيَادَةُ السَّبْقُ وَالتَّقَدُّمُ.","زيارة":"الزِّيَارَةُ الذَّهَابُ لِرُؤْيَةِ شَخْصٍ.","أيام":"الْأَيَّامُ جَمْعُ يَوْمٍ.","تمني":"تَمَنَّى الطِّفْلُ لُعْبَةً جَدِيدَةً.","تبني":"تَبَنَّى الزَّعِيمُ الْفِكْرَةَ وَدَافَعَ عَنْهَا.","تغني":"تَغَنَّى بِحُبِّ وَطَنِهِ.","فوري":"الْفَوْرِيُّ الَّذِي يَحْدُثُ فِي الْحَالِ.","دوري":"الدَّوْرِيُّ الَّذِي يَتَكَرَّرُ بِانْتِظَامٍ.","ثانوي":"الثَّانَوِيُّ الَّذِي يَلِي الْأَوَّلَ.","يقظة":"الْيَقَظَةُ الِانْتِبَاهُ وَالتَّيَقُّظُ.","ينابيع":"الْيَنَابِيعُ مَصَادِرُ الْمَاءِ النَّابِعَةِ مِنَ الْأَرْضِ.","نيابية":"النِّيَابِيَّةُ تَتَعَلَّقُ بِالنِّيَابَةِ وَالتَّمْثِيلِ.","تيسر":"التَّيَسُّرُ السُّهُولَةُ وَعَدَمُ الصُّعُوبَةِ.","تبييض":"التَّبْيِيضُ جَعْلُ الشَّيْءِ أَبْيَضَ.","رياضة":"الرِّيَاضَةُ النَّشَاطُ الْبَدَنِيُّ الْمُنَظَّمُ.","زيادة":"الزِّيَادَةُ الْإِضَافَةُ وَالنُّمُوُّ.","أيامية":"الْأَيَّامِيَّةُ مَا يَتَعَلَّقُ بِالْأَيَّامِ.","استشفى":"اِسْتَشْفَى الْمَرِيضُ وَتَعَافَى.","استدعى":"اِسْتَدْعَى الْمُدِيرُ مُوَظَّفَهُ.","تشافى":"تَشَافَى الْعَلِيلُ بَعْدَ رِعَايَةٍ طَوِيلَةٍ.","ماضوي":"الْمَاضَوِيُّ مَا يَنْتَمِي إِلَى الْمَاضِي.","حضاري":"الْحَضَارِيُّ مَا يَتَعَلَّقُ بِالْحَضَارَةِ.","دواري":"الدَّوَارِيُّ مَا يَدُورُ بِانْتِظَامٍ.","تراقض":"تَرَاقَضَ الزَّمِيلَانِ وَلَمْ يَجِدَا حَلًّا لِلْخِلَافِ.","تشكيل":"التَّشْكِيلُ إِعْطَاءُ الشَّيْءِ صُورَةً وَشَكْلًا مُعَيَّنًا.","تنظيم":"التَّنْظِيمُ وَضْعُ الْأَشْيَاءِ فِي تَرْتِيبٍ مُنَاسِبٍ.","يم":"الْيَمُّ الْبَحْرُ الْوَاسِعُ.","مكة":"مَكَّةُ الْمُكَرَّمَةُ حَيْثُ الْكَعْبَةُ الْمُشَرَّفَةُ.","مدينة":"الْمَدِينَةُ الْمُنَوَّرَةُ مَدِينَةُ الْحَبِيبِ الْمُصْطَفَى.","فلسطين":"فِلَسْطِينُ حُرَّةٌ بِإِذْنِ اللهِ.","سوريا":"سُورِيَّا تَحَرَّرَتْ مِنْ نِظَامِ الْأَسَدِ الْمُجْرِمِ.","غزة":"غَزَّةُ الْعِزَّةُ، غَزَّةُ هَاشِمٍ الْأَبِيَّةُ.","جمل":"الْجَمَلُ سَفِينَةُ الصَّحْرَاءِ، يَتَحَمَّلُ الْعَطَشَ أَيَّامًا طَوِيلَة.","أسد":"الْأَسَدُ مَلِكُ الْغَابَةِ، قَوِيٌّ وَشُجَاع.","أرنب":"الْأَرْنَبُ حَيَوَانٌ لَطِيفٌ يُحِبُّ الْجَزَر.","فيل":"الْفِيلُ أَكْبَرُ حَيَوَانٍ يَعِيشُ عَلَى الْيَابِسَة.","قطة":"الْقِطَّةُ حَيَوَانٌ أَلِيفٌ يُحِبُّ النَّظَافَة.","كلب":"الْكَلْبُ وَفِيٌّ لِصَاحِبِهِ وَيَحْرُسُ الْبَيْت.","حصان":"الْحِصَانُ حَيَوَانٌ جَمِيلٌ سَرِيعُ الْجَرْي.","سمكة":"السَّمَكَةُ تَعِيشُ فِي الْمَاءِ وَتَسْبَحُ بِزَعَانِفِهَا.","غزال":"الْغَزَالُ رَشِيقٌ وَجَمِيلٌ يَجْرِي بِسُرْعَة.","ثعلب":"الثَّعْلَبُ حَيَوَانٌ ذَكِيٌّ مَاكِر.","خروف":"الْخَرُوفُ يُعْطِينَا الصُّوفَ الدَّافِئ.","دجاجة":"الدَّجَاجَةُ تُعْطِينَا الْبَيْضَ كُلَّ يَوْم.","بطة":"الْبَطَّةُ تَسْبَحُ فِي الْمَاءِ وَتُحَرِّكُ جَنَاحَيْهَا.","نحلة":"النَّحْلَةُ تَصْنَعُ الْعَسَلَ وَتُلَقِّحُ الْأَزْهَار.","ذباب":"الذُّبَابُ حَشَرَةٌ يَجِبُ أَنْ نُبْعِدَهَا عَنِ الطَّعَام.","زرافة":"الزَّرَافَةُ لَهَا رَقَبَةٌ طَوِيلَةٌ تَصِلُ بِهَا لِلْأَشْجَار.","إوزة":"الْإِوَزَّةُ طَائِرٌ يُحِبُّ السِّبَاحَةَ فِي الْمَاء.","دودة":"الدُّودَةُ تُسَاعِدُ التُّرْبَةَ عَلَى أَنْ تُصْبِحَ خَصْبَة.","قرد":"الْقِرْدُ حَيَوَانٌ ذَكِيٌّ يُحِبُّ تَسَلُّقَ الْأَشْجَار.","شمس":"الشَّمْسُ تُعْطِينَا الضَّوْءَ وَالدِّفْءَ كُلَّ نَهَار.","قمر":"الْقَمَرُ يُنِيرُ السَّمَاءَ فِي اللَّيْل.","نجم":"النَّجْمُ يَلْمَعُ فِي السَّمَاءِ لَيْلًا.","ماء":"الْمَاءُ سِرُّ الْحَيَاةِ، نَشْرَبُهُ لِنَعِيش.","نار":"النَّارُ تُدْفِئُنَا، وَيَجِبُ أَنْ نَحْذَرَ مِنْهَا.","بحيرة":"الْبُحَيْرَةُ مَاءٌ عَذْبٌ تَعِيشُ فِيهِ الْأَسْمَاك.","زهرة":"الزَّهْرَةُ جَمِيلَةٌ وَرَائِحَتُهَا عَطِرَة.","وردة":"الْوَرْدَةُ رَمْزُ الْجَمَالِ وَالْمَحَبَّة.","شجرة":"الشَّجَرَةُ تُعْطِينَا الظِّلَّ وَالثَّمَرَ وَالْهَوَاءَ النَّقِيّ.","ضوء":"الضَّوْءُ يُسَاعِدُنَا عَلَى الرُّؤْيَةِ فِي الظَّلَام.","هلال":"الْهِلَالُ قَمَرٌ صَغِيرٌ يُبَشِّرُنَا بِبِدَايَةِ الشَّهْر.","لون":"اللَّوْنُ يُجَمِّلُ حَيَاتَنَا، وَالْأَلْوَانُ كَثِيرَة.","تفاح":"التُّفَّاحُ فَاكِهَةٌ لَذِيذَةٌ مُفِيدَةٌ لِلصِّحَّة.","تمر":"التَّمْرُ غِذَاءٌ حُلْوٌ وَمُبَارَك.","توت":"التُّوتُ فَاكِهَةٌ صَغِيرَةٌ حُلْوَةُ الْمَذَاق.","موز":"الْمَوْزُ فَاكِهَةٌ صَفْرَاءُ تُعْطِينَا طَاقَة.","عنب":"الْعِنَبُ فَاكِهَةٌ حُلْوَةٌ تَنْمُو فِي عَنَاقِيد.","برتقال":"الْبُرْتُقَالُ فَاكِهَةٌ غَنِيَّةٌ بِفِيتَامِين سِي.","حليب":"الْحَلِيبُ مَشْرُوبٌ مُفِيدٌ يُقَوِّي الْعِظَام.","عسل":"الْعَسَلُ غِذَاءٌ حُلْوٌ وَفِيهِ شِفَاءٌ لِلنَّاس.","خبز":"الْخُبْزُ طَعَامٌ أَسَاسِيٌّ نَأْكُلُهُ كُلَّ يَوْم.","بصل":"الْبَصَلُ يُضِيفُ نَكْهَةً طَيِّبَةً لِلطَّعَام.","جوز":"الْجَوْزُ مِنَ الْمُكَسَّرَاتِ الْمُفِيدَةِ لِلْعَقْل.","حلوى":"الْحَلْوَى لَذِيذَةٌ، وَنَأْكُلُهَا بِاعْتِدَال.","ليمون":"اللَّيْمُونُ فَاكِهَةٌ حَامِضَةٌ غَنِيَّةٌ بِالْفِيتَامِينَات.","رمان":"الرُّمَّانُ فَاكِهَةٌ ذُكِرَتْ فِي الْقُرْآنِ الْكَرِيم.","عين":"الْعَيْنُ نِعْمَةٌ نَرَى بِهَا الدُّنْيَا، فَلْنَشْكُرِ اللَّهَ عَلَيْهَا.","يد":"الْيَدُ نَعْمَلُ بِهَا وَنُسَاعِدُ بِهَا غَيْرَنَا.","أنف":"الْأَنْفُ نَشُمُّ بِهِ الرَّوَائِحَ وَنَتَنَفَّسُ بِهِ.","أذن":"الْأُذُنُ نَسْمَعُ بِهَا الْأَصْوَاتَ الْجَمِيلَة.","قلم":"الْقَلَمُ أَدَاةُ الْعِلْمِ، بِهِ نَكْتُبُ وَنَتَعَلَّم.","كتاب":"الْكِتَابُ خَيْرُ صَدِيقٍ، يُعَلِّمُنَا وَيُمْتِعُنَا.","مدرسة":"الْمَدْرَسَةُ بَيْتُ الْعِلْمِ، نَتَعَلَّمُ فِيهَا الْخَيْر.","كرسي":"الْكُرْسِيُّ نَجْلِسُ عَلَيْهِ لِنَقْرَأَ وَنَكْتُب.","طاولة":"الطَّاوِلَةُ نَضَعُ عَلَيْهَا كُتُبَنَا وَأَدَوَاتِنَا.","حقيبة":"الْحَقِيبَةُ نَحْمِلُ فِيهَا كُتُبَنَا إِلَى الْمَدْرَسَة.","ورقة":"الْوَرَقَةُ نَكْتُبُ عَلَيْهَا أَفْكَارَنَا الْجَمِيلَة.","صورة":"الصُّورَةُ تَحْفَظُ لَنَا الذِّكْرَيَاتِ الْجَمِيلَة.","نافذة":"النَّافِذَةُ نُطِلُّ مِنْهَا عَلَى الْعَالَمِ الْخَارِجِيّ.","صندوق":"الصُّنْدُوقُ نَحْفَظُ فِيهِ أَشْيَاءَنَا الثَّمِينَة.","جدول":"الْجَدْوَلُ يُنَظِّمُ وَقْتَنَا وَأَعْمَالَنَا.","رسالة":"الرِّسَالَةُ نُرْسِلُهَا لِمَنْ نُحِبُّ لِنَطْمَئِنَّ عَلَيْه.","بدلة":"الْبَدْلَةُ لِبَاسٌ أَنِيقٌ نَرْتَدِيهِ فِي الْمُنَاسَبَات.","حذاء":"الْحِذَاءُ يَحْمِي أَقْدَامَنَا حِينَ نَمْشِي.","ثوب":"الثَّوْبُ يَسْتُرُنَا وَيَقِينَا الْحَرَّ وَالْبَرْد.","خيمة":"الْخَيْمَةُ بَيْتٌ نَنْصِبُهُ حِينَ نُسَافِرُ أَوْ نُخَيِّم.","إبرة":"الْإِبْرَةُ صَغِيرَةٌ، نَخِيطُ بِهَا الثِّيَاب.","سيارة":"السَّيَّارَةُ تَنْقُلُنَا مِنْ مَكَانٍ إِلَى آخَرَ بِسُرْعَة.","مركب":"الْمَرْكَبُ يُبْحِرُ بِنَا فَوْقَ الْمَاء.","ساعة":"السَّاعَةُ تُعَلِّمُنَا قِيمَةَ الْوَقْتِ وَتَنْظِيمَه.","ميزان":"الْمِيزَانُ نَعْرِفُ بِهِ الْوَزْنَ بِالْعَدْلِ وَالدِّقَّة.","دلو":"الدَّلْوُ نَمْلَؤُهُ مَاءً وَنَحْمِلُهُ بِيَدِنَا.","عصا":"الْعَصَا نَتَوَكَّأُ عَلَيْهَا وَنُسَاعِدُ بِهَا أَنْفُسَنَا.","دواء":"الدَّوَاءُ يُشْفِينَا بِإِذْنِ اللَّهِ حِينَ نَمْرَض.","بيت":"الْبَيْتُ مَأْوَانَا، نَشْعُرُ فِيهِ بِالْأَمَانِ وَالْحُبّ.","باب":"الْبَابُ نَدْخُلُ مِنْهُ وَنَخْرُجُ، وَنَسْتَأْذِنُ قَبْلَه.","مزرعة":"الْمَزْرَعَةُ نَزْرَعُ فِيهَا الْخَيْرَ وَنَحْصُدُ الثَّمَر.","بستان":"الْبُسْتَانُ مَكَانٌ جَمِيلٌ مَلِيءٌ بِالْأَشْجَار.","خزانة":"الْخِزَانَةُ نُرَتِّبُ فِيهَا مَلَابِسَنَا وَأَغْرَاضَنَا.","نهر":"النَّهْرُ مَاءٌ جَارٍ يَسْقِي الْأَرْضَ وَالنَّاس.","بركة":"الْبِرْكَةُ مَاءٌ مُجْتَمِعٌ تَشْرَبُ مِنْهُ الْحَيَوَانَات.","جبل":"الْجَبَلُ شَامِخٌ وَعَالٍ، آيَةٌ مِنْ آيَاتِ اللَّه.","نجاح":"النَّجَاحُ ثَمَرَةُ الِاجْتِهَادِ وَالصَّبْر.","سلام":"السَّلَامُ تَحِيَّةُ الْإِسْلَامِ، وَفِيهِ مَحَبَّةٌ وَأَمَان.","هدية":"الْهَدِيَّةُ تَزْرَعُ الْمَحَبَّةَ بَيْنَ النَّاس.","ربيع":"الرَّبِيعُ فَصْلُ الْجَمَالِ، تُزْهِرُ فِيهِ الْأَرْض.","ذكي":"الذَّكِيُّ يُفَكِّرُ قَبْلَ أَنْ يَعْمَلَ وَيَتَعَلَّمُ بِسُرْعَة.","عزيز":"الْعَزِيزُ مَنْ يُكْرِمُهُ اللَّهُ وَيَرْفَعُ قَدْرَه.","لذيذ":"اللَّذِيذُ طَعَامٌ طَيِّبٌ نَشْكُرُ اللَّهَ عَلَيْه.","جميل":"الْجَمِيلُ كُلُّ مَا يَسُرُّ الْعَيْنَ وَالْقَلْب.","كبير":"الْكَبِيرُ نَحْتَرِمُهُ وَنُقَدِّرُهُ وَنُطِيعُه.","رشيق":"الرَّشِيقُ خَفِيفُ الْحَرَكَةِ، يَهْتَمُّ بِصِحَّتِه.","وفر":"الْوَفْرُ نِعْمَةٌ، نَشْكُرُهَا وَلَا نُسْرِف.","وعد":"الْوَعْدُ أَمَانَةٌ، وَالْمُسْلِمُ يَفِي بِوَعْدِه.","ذهب":"الذَّهَبُ مَعْدِنٌ ثَمِينٌ وَلَكِنَّ الْعِلْمَ أَثْمَنُ مِنْه.","ذرة":"الذَّرَةُ أَصْغَرُ شَيْءٍ، وَفِيهَا عَجَائِبُ خَلْقِ اللَّه.","كنز":"الْكَنْزُ مَالٌ ثَمِينٌ، وَأَعْظَمُ كَنْزٍ هُوَ الْعِلْمُ وَالْأَخْلَاق.","فوز":"الْفَوْزُ الْحَقِيقِيُّ هُوَ رِضَا اللَّهِ عَنَّا.","صحو":"الصَّحْوُ صَفَاءُ السَّمَاءِ بَعْدَ الْمَطَر.","نور":"النُّورُ يُضِيءُ الظَّلَامَ، وَالْعِلْمُ نُورُ الْقَلْب.","حلو":"الْحُلْوُ طَعْمٌ نُحِبُّهُ، وَالْكَلَامُ الْحُلْوُ يُحِبُّهُ النَّاس.","أخ":"الْأَخُ سَنَدُكَ فِي الْحَيَاةِ، أَحْسِنْ إِلَيْهِ.","أخذ":"أَخَذَ يَعْنِي تَنَاوَلَ الشَّيْءَ بِيَدِهِ.","أراك":"أَرَاكَ أَيْ أَنْظُرُ إِلَيْكَ بِعَيْنِي.","أرسل":"أَرْسَلَ اللَّهُ الْأَنْبِيَاءَ لِهِدَايَةِ النَّاس.","أرشد":"أَرْشَدَ يَعْنِي دَلَّ غَيْرَهُ عَلَى الْخَيْر.","أرضى":"أَرْضَى وَالِدَيْهِ بِبِرِّهِ وَطَاعَتِهِ.","أزلق":"أَزْلَقَ يَعْنِي جَعَلَهُ يَنْزَلِقُ بِسُرْعَة.","أستاذ":"الْأُسْتَاذُ يُعَلِّمُنَا، فَلْنَحْتَرِمْهُ وَنُصْغِ إِلَيْه.","أظهر":"أَظْهَرَ الْحَقَّ وَلَمْ يُخْفِه.","أعرض":"أَعْرَضَ يَعْنِي أَدَارَ وَجْهَهُ وَابْتَعَد.","ألفاظ":"الْأَلْفَاظُ الطَّيِّبَةُ صَدَقَةٌ نُقَدِّمُهَا.","أناخ":"أَنَاخَ الْجَمَلَ يَعْنِي أَجْلَسَهُ لِيَسْتَرِيح.","أول":"الْأَوَّلُ هُوَ مَا يَأْتِي قَبْلَ غَيْرِه.","إيقاظ":"إِيقَاظُ النَّائِمِ لِلصَّلَاةِ عَمَلٌ طَيِّب.","احترام":"الِاحْتِرَامُ أَسَاسُ الْمُعَامَلَةِ بَيْنَ النَّاس.","بحث":"الْبَحْثُ عَنِ الْعِلْمِ يَرْفَعُ صَاحِبَه.","بحر":"الْبَحْرُ وَاسِعٌ عَمِيقٌ، فِيهِ خَيْرٌ كَثِير.","بخور":"الْبَخُورُ رَائِحَتُهُ طَيِّبَةٌ تُعَطِّرُ الْمَكَان.","بدر":"الْبَدْرُ قَمَرٌ مُكْتَمِلٌ يُنِيرُ اللَّيْل.","برج":"الْبُرْجُ بِنَاءٌ عَالٍ يُرَى مِنْ بَعِيد.","برد":"الْبَرْدُ نَلْبَسُ فِيهِ ثِيَابًا دَافِئَة.","بساط":"الْبِسَاطُ نَفْرُشُهُ عَلَى الْأَرْضِ لِنَجْلِس.","بضع":"بِضْعٌ يَعْنِي عَدَدًا قَلِيلًا مِنَ الْأَشْيَاء.","بغل":"الْبَغْلُ حَيَوَانٌ قَوِيٌّ يَحْمِلُ الْأَحْمَال.","بقرة":"الْبَقَرَةُ تُعْطِينَا الْحَلِيبَ وَاللَّحْم.","بلغ":"بَلَغَ الْخَبَرُ يَعْنِي وَصَلَ وَانْتَشَر.","بنت":"الْبِنْتُ نِعْمَةٌ، نُرَبِّيهَا بِالْحُبِّ وَالْعِلْم.","بيض":"الْبَيْضُ غِذَاءٌ مُفِيدٌ نَأْكُلُهُ فِي الصَّبَاح.","تاريخ":"التَّارِيخُ يُعَلِّمُنَا مِنْ أَحْدَاثِ الْمَاضِي.","ترك":"تَرَكَ يَعْنِي أَبْقَى الشَّيْءَ وَابْتَعَدَ عَنْه.","تلميذ":"التِّلْمِيذُ يَتَعَلَّمُ وَيَجْتَهِدُ لِيَنْجَح.","تلميذة":"التِّلْمِيذَةُ الْمُجْتَهِدَةُ تُحِبُّ الْعِلْم.","ثقل":"الثِّقَلُ يَعْنِي الْوَزْنَ الْكَبِير.","ثلج":"الثَّلْجُ مَاءٌ مُتَجَمِّدٌ أَبْيَضُ بَارِد.","ثمر":"الثَّمَرُ هَدِيَّةُ الشَّجَرَةِ، نَأْكُلُهُ وَنَشْكُر.","جزل":"الْعَطَاءُ الْجَزْلُ يَعْنِي الْكَثِيرَ الْوَافِر.","جعل":"جَعَلَ اللَّهُ اللَّيْلَ لِنَسْتَرِيحَ فِيه.","جلس":"جَلَسَ يَعْنِي قَعَدَ فِي مَكَانِه.","جمع":"جَمَعَ الْأَشْيَاءَ يَعْنِي ضَمَّهَا مَعًا.","جناح":"الْجَنَاحُ يُسَاعِدُ الطَّائِرَ عَلَى الطَّيَرَان.","جو":"الْجَوُّ هُوَ حَالُ السَّمَاءِ مِنْ حَرٍّ أَوْ بَرْد.","جيش":"الْجَيْشُ يَحْمِي الْوَطَنَ وَيَدْفَعُ عَنْه.","حادث":"يَجِبُ أَنْ نَحْذَرَ لِنَتَجَنَّبَ الْحَادِث.","حارث":"الْحَارِثُ هُوَ الَّذِي يَزْرَعُ الْأَرْضَ وَيَفْلَحُهَا.","حاوي":"حَاوِي الشَّيْءِ مَنْ يَحْمِلُهُ وَيَضُمُّه.","حجر":"الْحَجَرُ صَلْبٌ، نَبْنِي بِهِ الْبُيُوت.","حذق":"الْحَذِقُ يَعْنِي الْمَاهِرَ فِي عَمَلِه.","حرص":"الْحِرْصُ عَلَى الْوَقْتِ مِنْ عَلَامَاتِ النَّجَاح.","حضن":"الْحُضْنُ يُشْعِرُنَا بِالْأَمَانِ وَالْحُب.","حظ":"الْحَظُّ نَصِيبٌ، وَالِاجْتِهَادُ خَيْرٌ مِنْه.","حفظ":"حِفْظُ الْقُرْآنِ نُورٌ لِلْقَلْب.","حلق":"الْحَلْقُ نَبْلَعُ بِهِ الطَّعَامَ وَالشَّرَاب.","حلم":"الْحُلْمُ مَا نَرَاهُ فِي نَوْمِنَا.","حمام":"الْحَمَامُ طَائِرٌ جَمِيلٌ رَمْزٌ لِلسَّلَام.","حوت":"الْحُوتُ أَكْبَرُ حَيَوَانٍ يَعِيشُ فِي الْبَحْر.","خلاص":"الْخَلَاصُ يَعْنِي النَّجَاةَ مِنَ الشِّدَّة.","خيط":"الْخَيْطُ نَخِيطُ بِهِ الثِّيَابَ الْمُمَزَّقَة.","دب":"الدُّبُّ حَيَوَانٌ كَبِيرٌ يُحِبُّ الْعَسَل.","دجاج":"الدَّجَاجُ يُعْطِينَا الْبَيْضَ وَاللَّحْم.","دخل":"دَخَلَ الْبَيْتَ يَعْنِي وَلَجَ إِلَيْه.","درج":"الدَّرَجُ نَصْعَدُ عَلَيْهِ إِلَى الْأَعْلَى.","درس":"الدَّرْسُ يُعَلِّمُنَا شَيْئًا جَدِيدًا كُلَّ يَوْم.","دعا":"دَعَا رَبَّهُ يَعْنِي طَلَبَ مِنْهُ بِخُشُوع.","دكان":"الدُّكَّانُ مَحَلٌّ صَغِيرٌ نَشْتَرِي مِنْه.","دمغ":"دَمَغَ الْوَرَقَةَ يَعْنِي وَضَعَ عَلَيْهَا عَلَامَة.","دنيا":"الدُّنْيَا دَارٌ نَعْمَلُ فِيهَا لِآخِرَتِنَا.","ذرع":"الذِّرَاعُ نَقِيسُ بِهَا الطُّولَ قَدِيمًا.","ذيل":"الذَّيْلُ نِهَايَةُ جِسْمِ الْحَيَوَان.","راوي":"الرَّاوِي هُوَ الَّذِي يَحْكِي الْقِصَّةَ وَيَنْقُلُهَا.","ربط":"رَبَطَ الْحَبْلَ يَعْنِي عَقَدَهُ وَشَدَّه.","ربع":"الرُّبْعُ جُزْءٌ مِنْ أَرْبَعَةِ أَجْزَاء.","رتب":"رَتَّبَ غُرْفَتَهُ يَعْنِي نَظَّمَهَا.","رجل":"الرَّجُلُ يَعْمَلُ وَيَسْعَى لِيُعِيلَ أُسْرَتَه.","رحلة":"الرِّحْلَةُ سَفَرٌ مُمْتِعٌ نَتَعَلَّمُ مِنْه.","رخص":"رَخُصَ السِّعْرُ يَعْنِي صَارَ قَلِيلًا.","رسم":"الرَّسْمُ فَنٌّ نُعَبِّرُ بِهِ عَنْ أَفْكَارِنَا.","رشة":"الرَّشَّةُ كَمِّيَّةٌ قَلِيلَةٌ نَرُشُّهَا.","رصاص":"الرَّصَاصُ مَعْدِنٌ ثَقِيلٌ لَيِّن.","رصيف":"الرَّصِيفُ نَمْشِي عَلَيْهِ بِأَمَانٍ جَانِبَ الطَّرِيق.","رضا":"الرِّضَا بِمَا قَسَمَ اللَّهُ كَنْزٌ لَا يَنْفَد.","رعد":"الرَّعْدُ صَوْتٌ قَوِيٌّ يُصَاحِبُ الْمَطَر.","رغب":"رَغِبَ فِي الْخَيْرِ يَعْنِي أَرَادَهُ وَأَحَبَّه.","رغف":"الرَّغِيفُ خُبْزٌ نَأْكُلُهُ وَنَشْكُرُ عَلَيْه.","رفع":"رَفَعَ الشَّيْءَ يَعْنِي حَمَلَهُ إِلَى الْأَعْلَى.","رفيق":"الرَّفِيقُ الصَّالِحُ يُعِينُكَ عَلَى الْخَيْر.","رقص":"الرَّقْصُ حَرَكَةٌ مُنَظَّمَةٌ مَعَ الْإِيقَاع.","رقم":"الرَّقْمُ نَعُدُّ بِهِ الْأَشْيَاءَ وَنَحْسُب.","ركب":"رَكِبَ السَّيَّارَةَ يَعْنِي جَلَسَ فِيهَا لِيُسَافِر.","ركض":"رَكَضَ يَعْنِي جَرَى بِسُرْعَة.","رمز":"الرَّمْزُ عَلَامَةٌ تَدُلُّ عَلَى مَعْنًى.","رمل":"الرَّمْلُ حُبَيْبَاتٌ صَغِيرَةٌ فِي الصَّحْرَاء.","رنة":"الرَّنَّةُ صَوْتٌ يُنَبِّهُنَا كَرَنِينِ الْهَاتِف.","رهن":"الرَّهْنُ شَيْءٌ نَتْرُكُهُ ضَمَانًا.","روح":"الرُّوحُ سِرٌّ مِنْ خَلْقِ اللَّهِ فِينَا.","ريشة":"الرِّيشَةُ خَفِيفَةٌ، تُغَطِّي جِسْمَ الطَّائِر.","زبد":"الزُّبْدُ مَا يَطْفُو فَوْقَ الْحَلِيبِ مِنْ دَسَم.","زجاج":"الزُّجَاجُ شَفَّافٌ نَرَى مِنْ خِلَالِه.","زجاجة":"الزُّجَاجَةُ وِعَاءٌ شَفَّافٌ نَحْفَظُ فِيهِ السَّوَائِل.","زحف":"زَحَفَ الطِّفْلُ يَعْنِي تَحَرَّكَ عَلَى بَطْنِه.","زرع":"زَرَعَ الْبَذْرَةَ فَنَبَتَتْ شَجَرَةً مُبَارَكَة.","زعل":"الزَّعَلُ شُعُورٌ يَزُولُ بِالْكَلِمَةِ الطَّيِّبَة.","زغب":"الزَّغَبُ رِيشٌ نَاعِمٌ صَغِيرٌ عَلَى الطَّائِر.","زفة":"الزَّفَّةُ فَرَحٌ نُشَارِكُ بِهِ أَهْلَنَا.","زقاق":"الزُّقَاقُ طَرِيقٌ ضَيِّقٌ بَيْنَ الْبُيُوت.","زلزال":"الزِّلْزَالُ اهْتِزَازُ الْأَرْضِ، نَدْعُو اللَّهَ عِنْدَه.","زلزل":"زَلْزَلَ يَعْنِي حَرَّكَ بِشِدَّةٍ وَهَزَّ.","زمن":"الزَّمَنُ يَمْضِي، فَلْنَسْتَثْمِرْهُ فِي الْخَيْر.","زند":"الزَّنْدُ جُزْءٌ مِنَ الذِّرَاعِ قُرْبَ الْكَفّ.","زوج":"الزَّوْجُ اثْنَانِ مَعًا، كَالْجَوْرَبَيْن.","زيت":"الزَّيْتُ نَطْبُخُ بِهِ، وَزَيْتُ الزَّيْتُونِ مُبَارَك.","ستر":"السَّتْرُ إِخْفَاءُ الْعَيْبِ وَعَدَمُ فَضْحِه.","سجل":"سَجَّلَ الْمَعْلُومَةَ يَعْنِي كَتَبَهَا لِيَحْفَظَهَا.","سحاب":"السَّحَابُ يَحْمِلُ الْمَطَرَ رَحْمَةً مِنَ اللَّه.","سخل":"السَّخْلُ هُوَ صَغِيرُ الْغَنَم.","سطح":"السَّطْحُ أَعْلَى الْبَيْتِ، نَرَى مِنْهُ السَّمَاء.","سفر":"السَّفَرُ يُعَلِّمُنَا وَيُوَسِّعُ مَدَارِكَنَا.","سقف":"السَّقْفُ يُظَلِّلُنَا وَيَحْمِينَا فِي بُيُوتِنَا.","سكر":"السُّكَّرُ حُلْوٌ، نَأْكُلُهُ بِاعْتِدَالٍ لِصِحَّتِنَا.","سلة":"السَّلَّةُ نَضَعُ فِيهَا الْفَاكِهَةَ وَالْأَغْرَاض.","سلم":"السُّلَّمُ نَصْعَدُ بِهِ إِلَى الْأَمَاكِنِ الْعَالِيَة.","سمع":"السَّمْعُ نِعْمَةٌ نَسْمَعُ بِهَا، فَلْنَشْكُرِ اللَّه.","سمك":"السَّمَكُ غِذَاءٌ مُفِيدٌ يَعِيشُ فِي الْمَاء.","سمن":"السَّمْنُ دُهْنٌ نَطْبُخُ بِهِ طَعَامَنَا.","سنة":"السَّنَةُ اثْنَا عَشَرَ شَهْرًا، نَغْتَنِمُهَا بِالْخَيْر.","سهل":"السَّهْلُ أَرْضٌ مُسْتَوِيَةٌ سَهْلَةُ الزِّرَاعَة.","شاي":"الشَّايُ مَشْرُوبٌ دَافِئٌ نَشْرَبُهُ مَعَ الْأَهْل.","شبه":"الشَّبَهُ يَعْنِي التَّمَاثُلَ بَيْنَ شَيْئَيْن.","شجر":"الشَّجَرُ يُنَقِّي الْهَوَاءَ وَيُعْطِينَا الثَّمَر.","شراك":"الشِّرَاكُ سَيْرٌ يَرْبِطُ الْحِذَاءَ بِالْقَدَم.","شرط":"الشَّرْطُ مَا يَجِبُ تَحْقِيقُهُ لِنَنَالَ شَيْئًا.","شعر":"الشَّعْرُ يُغَطِّي رُؤُوسَنَا، نَعْتَنِي بِنَظَافَتِه.","شفاف":"الشَّفَّافُ مَا نَرَى مِنْ خِلَالِه.","شكل":"الشَّكْلُ هُوَ هَيْئَةُ الشَّيْءِ وَصُورَتُه.","صباغ":"الصَّبَّاغُ يُلَوِّنُ الْأَشْيَاءَ بِالْأَلْوَان.","صحا":"صَحَا مِنْ نَوْمِهِ يَعْنِي اسْتَيْقَظَ وَنَهَض.","صدر":"الصَّدْرُ جُزْءٌ مِنْ جِسْمِنَا فِيهِ الْقَلْب.","صدق":"الصِّدْقُ خُلُقٌ جَمِيلٌ يُحِبُّهُ اللَّهُ وَالنَّاس.","صغير":"الصَّغِيرُ نَرْحَمُهُ وَنَعْتَنِي بِه.","صفر":"الصِّفْرُ رَقْمٌ يَدُلُّ عَلَى لَا شَيْء.","صقر":"الصَّقْرُ طَائِرٌ قَوِيٌّ حَادُّ الْبَصَر.","صوت":"الصَّوْتُ نَسْمَعُهُ بِآذَانِنَا، وَنُحْسِنُ اسْتِخْدَامَه.","صوف":"الصُّوفُ يَأْتِي مِنَ الْغَنَمِ وَيُدْفِئُنَا.","ضحك":"الضَّحِكُ الْمُعْتَدِلُ يُسْعِدُ الْقَلْبَ وَالنَّاس.","ضفدع":"الضِّفْدَعُ يَعِيشُ قُرْبَ الْمَاءِ وَيَقْفِز.","ضيف":"الضَّيْفُ نُكْرِمُهُ، فَإِكْرَامُهُ مِنَ الْإِيمَان.","طبخ":"الطَّبْخُ تَحْضِيرُ الطَّعَامِ بِالنَّار.","طبل":"الطَّبْلُ آلَةٌ نَقْرَعُهَا فَتُصْدِرُ صَوْتًا.","طرف":"الطَّرَفُ هُوَ النِّهَايَةُ أَوِ الْحَافَّة.","طويل":"الطَّوِيلُ يَعْنِي الْمُمْتَدَّ كَثِيرًا فِي الطُّول.","طير":"الطَّيْرُ يُحَلِّقُ فِي السَّمَاءِ بِجَنَاحَيْه.","ظبي":"الظَّبْيُ غَزَالٌ صَغِيرٌ جَمِيلُ الْعَيْنَيْن.","ظرف":"الظَّرْفُ غِلَافٌ نَضَعُ فِيهِ الرِّسَالَة.","ظفر":"الظُّفْرُ يَنْمُو فِي أَطْرَافِ أَصَابِعِنَا.","ظل":"الظِّلُّ يَحْمِينَا مِنْ حَرِّ الشَّمْس.","عبث":"الْعَبَثُ يَعْنِي اللَّعِبَ بِلَا فَائِدَة.","عرب":"الْعَرَبُ قَوْمٌ نَزَلَ بِلُغَتِهِمُ الْقُرْآن.","عروس":"الْعَرُوسُ تَفْرَحُ فِي يَوْمِ زَوَاجِهَا.","عشب":"الْعُشْبُ نَبَاتٌ أَخْضَرُ تَأْكُلُهُ الْحَيَوَانَات.","عطش":"الْعَطَشُ حَاجَةٌ لِلْمَاء، نَشْكُرُ نِعْمَةَ الرِّيّ.","عظيم":"الْعَظِيمُ كَبِيرُ الْقَدْرِ، وَاللَّهُ أَعْظَمُ كُلِّ شَيْء.","عفو":"الْعَفْوُ عَنِ الْمُسِيءِ خُلُقُ الْكِرَام.","عقرب":"الْعَقْرَبُ حَشَرَةٌ نَحْذَرُهَا فَلَهَا لَدْغَةٌ مُؤْذِيَة.","عقل":"الْعَقْلُ نِعْمَةٌ نُفَكِّرُ بِهَا فِي الْخَيْر.","عمر":"الْعُمْرُ أَيَّامٌ مَعْدُودَةٌ نَمْلَؤُهَا بِالصَّالِحَات.","عنق":"الْعُنُقُ يَحْمِلُ رَأْسَنَا وَيُحَرِّكُه.","غراب":"الْغُرَابُ طَائِرٌ أَسْوَدُ ذَكِيّ.","غنم":"الْغَنَمُ تُعْطِينَا الصُّوفَ وَاللَّبَنَ وَاللَّحْم.","غوص":"الْغَوْصُ نُزُولٌ تَحْتَ الْمَاءِ لِاكْتِشَافِه.","فارة":"الْفَأْرَةُ حَيَوَانٌ صَغِيرٌ سَرِيعُ الْحَرَكَة.","فاكهة":"الْفَاكِهَةُ حُلْوَةٌ وَمُفِيدَةٌ، نِعْمَةٌ نَشْكُرُهَا.","فتح":"فَتَحَ الْبَابَ يَعْنِي جَعَلَهُ مَفْتُوحًا.","فراش":"الْفِرَاشُ نَنَامُ عَلَيْهِ لِنَرْتَاح.","فراشة":"الْفَرَاشَةُ حَشَرَةٌ جَمِيلَةٌ مُلَوَّنَةُ الْأَجْنِحَة.","فراغ":"الْفَرَاغُ وَقْتٌ نَمْلَؤُهُ بِالنَّافِعِ الْمُفِيد.","فرس":"الْفَرَسُ حِصَانٌ أَصِيلٌ سَرِيعُ الْجَرْي.","فرش":"فَرَشَ الْبِسَاطَ يَعْنِي بَسَطَهُ عَلَى الْأَرْض.","فرغ":"فَرَغَ الْإِنَاءُ يَعْنِي خَلَا مِمَّا فِيه.","فوه":"الْفُوهُ هُوَ الْفَمُ، نَنْطِقُ بِهِ الطَّيِّب.","قسط":"الْقِسْطُ يَعْنِي الْعَدْلَ وَالْإِنْصَاف.","قصة":"الْقِصَّةُ تُمْتِعُنَا وَتُعَلِّمُنَا حِكَمًا جَمِيلَة.","قفص":"الْقَفَصُ مَكَانٌ مُغْلَقٌ، وَالطَّيْرُ يُحِبُّ الْحُرِّيَّة.","قميص":"الْقَمِيصُ ثَوْبٌ نَلْبَسُهُ فَوْقَ صَدْرِنَا.","قوت":"الْقُوتُ هُوَ الطَّعَامُ الَّذِي نَعِيشُ بِه.","قوي":"الْقَوِيُّ يُسَاعِدُ الضَّعِيفَ وَلَا يَظْلِمُه.","كتف":"الْكَتِفُ جُزْءٌ مِنْ أَعْلَى الذِّرَاع.","كثير":"الْكَثِيرُ يَعْنِي الْعَدَدَ الْوَفِيرَ الْكَبِير.","كثيرة":"النِّعَمُ كَثِيرَةٌ حَوْلَنَا، فَلْنَشْكُرِ اللَّه.","كرة":"الْكُرَةُ نَلْعَبُ بِهَا وَنَمْرَحُ مَعَ أَصْحَابِنَا.","كره":"الْكُرْهُ شُعُورٌ سَيِّئٌ، وَالْحُبُّ أَجْمَلُ مِنْه.","كسر":"كَسَرَ الشَّيْءَ يَعْنِي جَعَلَهُ قِطَعًا.","كشف":"كَشَفَ الْغِطَاءَ يَعْنِي أَزَالَهُ وَأَظْهَرَ مَا تَحْتَه.","لبس":"لَبِسَ الثَّوْبَ يَعْنِي ارْتَدَاه.","لبن":"اللَّبَنُ مَشْرُوبٌ مُفِيدٌ يُقَوِّي أَجْسَامَنَا.","لحم":"اللَّحْمُ غِذَاءٌ يُعْطِينَا الْقُوَّةَ وَالطَّاقَة.","لعب":"اللَّعِبُ الْمُفِيدُ يُسْعِدُنَا وَيُنَمِّي مَهَارَاتِنَا.","لغة":"اللُّغَةُ الْعَرَبِيَّةُ لُغَةُ الْقُرْآنِ، نَفْخَرُ بِهَا.","لغز":"اللُّغْزُ سُؤَالٌ صَعْبٌ نُفَكِّرُ لِنَحُلَّه.","لفظ":"اللَّفْظُ كَلِمَةٌ نَنْطِقُهَا، فَلْتَكُنْ طَيِّبَة.","ماضي":"الْمَاضِي وَقْتٌ مَضَى، نَتَعَلَّمُ مِنْهُ لِغَدِنَا.","متر":"الْمِتْرُ وَحْدَةٌ نَقِيسُ بِهَا الطُّول.","مثل":"الْمَثَلُ قَوْلٌ حَكِيمٌ مُخْتَصَرٌ مُفِيد.","مدح":"الْمَدْحُ بِصِدْقٍ يُشَجِّعُ عَلَى الْخَيْر.","مرض":"الْمَرَضُ يَزُولُ بِإِذْنِ اللَّهِ، نَصْبِرُ وَنَتَدَاوَى.","مزحة":"الْمِزْحَةُ اللَّطِيفَةُ تُدْخِلُ السُّرُورَ بِلَا أَذًى.","مسجد":"الْمَسْجِدُ بَيْتُ اللَّهِ، نُصَلِّي فِيهِ بِخُشُوع.","مطر":"الْمَطَرُ رَحْمَةٌ مِنَ اللَّهِ، يَسْقِي الْأَرْض.","مكتب":"الْمَكْتَبُ نَجْلِسُ إِلَيْهِ لِنَقْرَأَ وَنَكْتُب.","ملح":"الْمِلْحُ يُضِيفُ نَكْهَةً لِطَعَامِنَا.","ملك":"الْمَلِكُ يَحْكُمُ بِالْعَدْلِ بَيْنَ النَّاس.","مناخ":"الْمُنَاخُ هُوَ حَالُ الطَّقْسِ فِي مَكَانٍ مَا.","منفذ":"الْمَنْفَذُ طَرِيقٌ نَخْرُجُ مِنْه.","مواظبة":"الْمُوَاظَبَةُ عَلَى الْعَمَلِ سِرُّ النَّجَاح.","نبض":"النَّبْضُ حَرَكَةُ الْقَلْبِ الَّتِي تَدُلُّ عَلَى الْحَيَاة.","نبي":"النَّبِيُّ يُبَلِّغُنَا رِسَالَةَ اللَّهِ، نُحِبُّهُ وَنَتَّبِعُه.","نجا":"نَجَا مِنَ الْخَطَرِ يَعْنِي سَلِمَ مِنْه.","نجح":"نَجَحَ الْمُجْتَهِدُ بَعْدَ تَعَبٍ وَصَبْر.","نخل":"النَّخْلُ يُعْطِينَا التَّمْرَ الْحُلْوَ الْمُبَارَك.","نرثها":"نَرِثُهَا يَعْنِي نَأْخُذُهَا مِمَّنْ قَبْلَنَا.","نسب":"النَّسَبُ هُوَ صِلَةُ الْقَرَابَةِ بَيْنَ النَّاس.","نسج":"نَسَجَ الْقُمَاشَ يَعْنِي صَنَعَهُ مِنَ الْخُيُوط.","نشاط":"النَّشَاطُ يَجْعَلُنَا نُنْجِزُ أَعْمَالَنَا بِحَيَوِيَّة.","نشر":"نَشَرَ الْخَيْرَ يَعْنِي بَثَّهُ بَيْنَ النَّاس.","نصف":"النِّصْفُ جُزْءٌ مِنِ اثْنَيْنِ مُتَسَاوِيَيْن.","نظام":"النِّظَامُ يُرَتِّبُ حَيَاتَنَا وَيُسَهِّلُ أُمُورَنَا.","نظر":"النَّظَرُ نِعْمَةٌ نَنْظُرُ بِهَا إِلَى الْجَمِيل.","نفخ":"نَفَخَ فِي الْبَالُونِ يَعْنِي مَلَأَهُ بِالْهَوَاء.","نفذ":"نَفَذَ الْأَمْرَ يَعْنِي طَبَّقَهُ وَأَتَمَّه.","نقاش":"النِّقَاشُ الْهَادِئُ يُوصِلُنَا إِلَى الْحَقّ.","نكث":"نَكَثَ الْعَهْدَ يَعْنِي نَقَضَهُ، وَهَذَا خُلُقٌ سَيِّئ.","نمر":"النَّمِرُ حَيَوَانٌ قَوِيٌّ سَرِيعٌ مُفْتَرِس.","نهض":"نَهَضَ يَعْنِي قَامَ وَوَقَفَ بَعْدَ جُلُوس.","نوه":"نَوَّهَ بِالشَّيْءِ يَعْنِي أَشَارَ إِلَيْهِ وَنَبَّه.","هرم":"الْهَرَمُ بِنَاءٌ ضَخْمٌ قَدِيمٌ مُثَلَّثُ الشَّكْل.","هنا":"هُنَا تَدُلُّ عَلَى الْمَكَانِ الْقَرِيبِ مِنَّا.","وارث":"الْوَارِثُ مَنْ يَأْخُذُ مِيرَاثَ مَنْ سَبَقَه.","وارثون":"الْوَارِثُونَ هُمُ الَّذِينَ يَرِثُونَ مَا تُرِكَ لَهُم.","واظب":"وَاظَبَ عَلَى عَمَلِهِ يَعْنِي دَاوَمَ عَلَيْه.","وبر":"الْوَبَرُ شَعْرٌ نَاعِمٌ يُغَطِّي جِسْمَ الْجَمَل.","وتر":"الْوَتَرُ خَيْطٌ مَشْدُودٌ يُصْدِرُ نَغَمًا.","وتد":"الْوَتَدُ مِسْمَارٌ مِنْ خَشَبٍ يُدَقُّ فِي الْأَرْضِ لِيَرْبِطَ بِهِ الرَّاعِي حَيَوَانَاتِهِ.","وتين":"الْوَتِينُ عِرْقٌ كَبِيرٌ مُتَّصِلٌ بِالْقَلْب.","وجه":"الْوَجْهُ نُقَابِلُ بِهِ النَّاسَ بِابْتِسَامَةٍ طَيِّبَة.","وحش":"الْوَحْشُ هُوَ الِاسْمُ الْأَصْلِيُّ لِنِظَامِ الْأَسَدِ الْبَائِدِ.","وحل":"الْوَحْلُ طِينٌ لَزِجٌ نَحْذَرُ الِانْزِلَاقَ فِيه.","وخز":"الْوَخْزُ أَلَمٌ خَفِيفٌ كَوَخْزِ الْإِبْرَة.","ودع":"وَدَّعَ صَاحِبَهُ يَعْنِي قَالَ لَهُ مَعَ السَّلَامَة.","ورق":"الْوَرَقُ نَكْتُبُ عَلَيْهِ، وَوَرَقُ الشَّجَرِ أَخْضَر.","وزن":"الْوَزْنُ يُخْبِرُنَا كَمْ يَثْقُلُ الشَّيْء.","وسط":"الْوَسَطُ هُوَ مُنْتَصَفُ الشَّيْءِ بَيْنَ طَرَفَيْه.","وصل":"وَصَلَ إِلَى هَدَفِهِ بَعْدَ اجْتِهَادٍ وَصَبْر.","وضع":"وَضَعَ الشَّيْءَ يَعْنِي جَعَلَهُ فِي مَكَانِه.","وطن":"الْوَطَنُ بَيْتُنَا الْكَبِيرُ، نُحِبُّهُ وَنَحْمِيه.","وطيد":"الْوَطِيدُ يَعْنِي الْقَوِيَّ الثَّابِتَ الرَّاسِخ.","وعاظ":"الْوُعَّاظُ يُذَكِّرُونَ النَّاسَ بِالْخَيْرِ وَالتَّقْوَى.","وغد":"الْوَغْدُ هُوَ سَيِّئُ الْأَخْلَاقِ، نَبْتَعِدُ عَنْه.","وقت":"الْوَقْتُ كَالسَّيْفِ، نَسْتَثْمِرُهُ فِي الْمُفِيد.","وكر":"الْوَكْرُ عُشُّ الطَّائِرِ يَأْوِي إِلَيْه.","ولد":"الْوَلَدُ الصَّالِحُ قُرَّةُ عَيْنٍ لِوَالِدَيْه.","ومض":"وَمَضَ الْبَرْقُ يَعْنِي لَمَعَ لَمْعَةً سَرِيعَة.","وهج":"الْوَهَجُ ضَوْءٌ قَوِيٌّ سَاطِعٌ كَوَهَجِ النَّار.","ويل":"الْوَيْلُ كَلِمَةُ وَعِيدٍ لِلْمُسِيء.","يابس":"الْيَابِسُ يَعْنِي الْجَافَّ الَّذِي لَا مَاءَ فِيه.","ياسمين":"الْيَاسَمِينُ زَهْرَةٌ بَيْضَاءُ عَطِرَةُ الرَّائِحَة.","يحظى":"يَحْظَى بِالشَّيْءِ يَعْنِي يَنَالُهُ وَيَفُوزُ بِه.","يرثي":"يَرْثِي يَعْنِي يَحْزَنُ لِفِرَاقِ أَحَد.","يشبه":"يُشْبِهُ يَعْنِي يُمَاثِلُ وَيُقَارِبُ فِي الشَّكْل.","يوم":"الْيَوْمُ فُرْصَةٌ جَدِيدَةٌ نَمْلَؤُهَا بِالْخَيْر.","حب":"الْحُبُّ شُعُورٌ جَمِيلٌ يَجْمَعُ الْقُلُوب.","بطريق":"الْبِطْرِيقُ طَائِرٌ يَعِيشُ فِي الْأَمَاكِنِ الْبَارِدَة.","ملعب":"الْمَلْعَبُ مَكَانٌ نَلْعَبُ فِيهِ وَنَمْرَح.","مكتبة":"الْمَكْتَبَةُ بَيْتُ الْكُتُبِ، نَقْرَأُ فِيهَا وَنَتَعَلَّم.","بلبل":"الْبُلْبُلُ طَائِرٌ صَغِيرٌ عَذْبُ الصَّوْت.","بنفسج":"الْبَنَفْسَجُ زَهْرَةٌ جَمِيلَةٌ بِلَوْنٍ بَنَفْسَجِيّ.","حطب":"الْحَطَبُ خَشَبٌ نُشْعِلُ بِهِ النَّارَ لِنَدْفَأ.","قلب":"الْقَلْبُ يَنْبِضُ بِالْحَيَاةِ، نَمْلَؤُهُ بِالْخَيْر.","حرب":"الْحَرْبُ شَرٌّ، وَالسَّلَامُ خَيْرٌ نَدْعُو إِلَيْه.","جبهة":"الْجَبْهَةُ جُزْءٌ مِنْ أَعْلَى الْوَجْه.","نبتة":"النَّبْتَةُ نَبَاتٌ صَغِيرٌ نَسْقِيهِ لِيَكْبُر.","زبدة":"الزُّبْدَةُ طَعَامٌ لَذِيذٌ نَأْخُذُهُ مِنَ الْحَلِيب.","ربطة":"الرَّبْطَةُ عُقْدَةٌ نَشُدُّ بِهَا الْأَشْيَاء.","خراب":"الْخَرَابُ ضِدُّ الْعِمَارَةِ، نُعَمِّرُ وَلَا نُخَرِّب.","شراب":"الشَّرَابُ سَائِلٌ نَشْرَبُهُ حِينَ نَعْطَش.","تراب":"التُّرَابُ أَصْلُ النَّبَاتِ، مِنْهُ يَنْمُو الزَّرْع.","مختبر":"الْمُخْتَبَرُ مَكَانٌ نُجْرِي فِيهِ التَّجَارِب.","زبرجد":"الزَّبَرْجَدُ حَجَرٌ كَرِيمٌ أَخْضَرُ جَمِيل.","أربعة":"الْأَرْبَعَةُ عَدَدٌ بَعْدَ الثَّلَاثَة.","مزبلة":"الْمَزْبَلَةُ مَكَانُ النِّفَايَاتِ، نُبْعِدُهَا عَنْ بُيُوتِنَا.","ملاعب":"الْمَلَاعِبُ أَمَاكِنُ نَلْعَبُ فِيهَا وَنَمْرَح.","مكاتب":"الْمَكَاتِبُ أَمَاكِنُ نَعْمَلُ وَنَكْتُبُ فِيهَا.","عجائب":"الْعَجَائِبُ أُمُورٌ غَرِيبَةٌ تُدْهِشُنَا فِي الْكَوْن.","أقارب":"الْأَقَارِبُ أَهْلُنَا، نَصِلُهُمْ وَنُحْسِنُ إِلَيْهِم.","تجارب":"التَّجَارُبُ نَتَعَلَّمُ مِنْهَا وَنَكْبُرُ بِهَا.","مصائب":"الْمَصَائِبُ نَصْبِرُ عَلَيْهَا وَنَحْتَسِبُ أَجْرَهَا.","كواكب":"الْكَوَاكِبُ أَجْرَامٌ تَدُورُ حَوْلَ الشَّمْس.","مشارب":"الْمَشَارِبُ أَمَاكِنُ نَشْرَبُ مِنْهَا الْمَاء.","مربية":"الْمُرَبِّيَةُ تَعْتَنِي بِالْأَطْفَالِ وَتُرَبِّيهِم.","تبن":"التِّبْنُ بَقَايَا الزَّرْعِ، تَأْكُلُهُ بَعْضُ الْحَيَوَانَات.","زتن":"كَلِمَةٌ نَتَدَرَّبُ بِهَا عَلَى شَكْلِ التَّاء.","موت":"الْمَوْتُ حَقٌّ، وَنَعْمَلُ الصَّالِحَاتِ لِمَا بَعْدَه.","سكت":"سَكَتَ يَعْنِي تَوَقَّفَ عَنِ الْكَلَامِ وَصَمَت.","سمت":"السَّمْتُ الْحَسَنُ هُوَ الْأَدَبُ وَحُسْنُ الْهَيْئَة.","صمت":"الصَّمْتُ حِكْمَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ خَيْرٌ مِنْه.","نحت":"النَّحْتُ فَنُّ تَشْكِيلِ الْحَجَرِ أَوِ الْخَشَب.","نتف":"نَتَفَ يَعْنِي نَزَعَ الشَّيْءَ بِأَطْرَافِ أَصَابِعِه.","بيوت":"الْبُيُوتُ مَسَاكِنُنَا، نَشْعُرُ فِيهَا بِالْأَمَان.","ثبات":"الثَّبَاتُ عَلَى الْحَقِّ مِنْ صِفَاتِ الْأَقْوِيَاء.","فرات":"الْفُرَاتُ نَهْرٌ عَظِيمٌ عَذْبُ الْمَاء.","تمساح":"التِّمْسَاحُ حَيَوَانٌ قَوِيٌّ يَعِيشُ فِي الْأَنْهَار.","تمثال":"التِّمْثَالُ مُجَسَّمٌ مَنْحُوتٌ يُشْبِهُ شَيْئًا.","تنانير":"التَّنَانِيرُ أَفْرَانٌ نَخْبِزُ فِيهَا الْخُبْز.","تفاحة":"التُّفَّاحَةُ ثَمَرَةٌ لَذِيذَةٌ مُفِيدَةٌ لِلصِّحَّة.","كتابة":"الْكِتَابَةُ تَحْفَظُ الْعِلْمَ وَتَنْقُلُ الْأَفْكَار.","نتيجة":"النَّتِيجَةُ ثَمَرَةُ الْعَمَلِ وَالِاجْتِهَاد.","وترية":"الْآلَةُ الْوَتَرِيَّةُ تُصْدِرُ نَغَمًا بِأَوْتَارِهَا.","رتيب":"الرَّتِيبُ هُوَ الَّذِي لَا يَتَغَيَّرُ وَيُمَلّ.","وتيرة":"الْوَتِيرَةُ هِيَ نَمَطُ سَيْرِ الشَّيْءِ وَإِيقَاعُه.","أتراب":"الْأَتْرَابُ هُمُ الْأَصْحَابُ فِي نَفْسِ السِّنّ.","سبت":"السَّبْتُ يَوْمٌ مِنْ أَيَّامِ الْأُسْبُوع.","نعت":"النَّعْتُ صِفَةٌ نَصِفُ بِهَا الشَّيْء.","مقت":"الْمَقْتُ هُوَ الْكُرْهُ الشَّدِيد.","ملكوت":"الْمَلَكُوتُ هُوَ مُلْكُ اللَّهِ الْعَظِيمُ فِي السَّمَاوَات.","ياقوت":"الْيَاقُوتُ حَجَرٌ كَرِيمٌ أَحْمَرُ ثَمِين.","عنكبوت":"الْعَنْكَبُوتُ حَشَرَةٌ تَنْسِجُ بَيْتًا مِنْ خُيُوط.","نتاج":"النِّتَاجُ هُوَ ثَمَرَةُ الْعَمَلِ وَمَا يَنْتُجُ عَنْه.","كثر":"كَثُرَ الشَّيْءُ يَعْنِي زَادَ وَأَصْبَحَ كَثِيرًا.","نثر":"النَّثْرُ كَلَامٌ جَمِيلٌ بِلَا وَزْنٍ وَلَا قَافِيَة.","لثة":"اللِّثَةُ تُحِيطُ بِأَسْنَانِنَا، نَعْتَنِي بِنَظَافَتِهَا.","وثب":"وَثَبَ يَعْنِي قَفَزَ بِقُوَّةٍ إِلَى الْأَمَام.","رثة":"الثِّيَابُ الرَّثَّةُ هِيَ الْبَالِيَةُ الْقَدِيمَة.","لبث":"لَبِثَ فِي الْمَكَانِ يَعْنِي مَكَثَ وَبَقِيَ فِيه.","ورث":"وَرِثَ يَعْنِي أَخَذَ مَا تَرَكَهُ لَهُ مَنْ سَبَقَه.","حرث":"الْحَرْثُ هُوَ شَقُّ الْأَرْضِ لِزِرَاعَتِهَا.","إرث":"الْإِرْثُ مَا يَتْرُكُهُ السَّابِقُونَ لِمَنْ بَعْدَهُم.","ثمار":"الثِّمَارُ خَيْرَاتٌ تُعْطِينَاهَا الْأَشْجَار.","ثلاثة":"الثَّلَاثَةُ عَدَدٌ بَعْدَ الِاثْنَيْن.","نثار":"النِّثَارُ هُوَ مَا يُنْثَرُ وَيُلْقَى مُتَفَرِّقًا.","مثال":"الْمِثَالُ يُوَضِّحُ الْفِكْرَةَ وَيُقَرِّبُهَا.","وثاق":"الْوَثَاقُ هُوَ مَا يُرْبَطُ بِهِ الشَّيْءُ بِإِحْكَام.","دثار":"الدِّثَارُ ثَوْبٌ نَتَغَطَّى بِهِ لِنَدْفَأ.","رثاء":"الرِّثَاءُ كَلَامُ حُزْنٍ عَلَى مَنْ فَقَدْنَاه.","حديث":"الْحَدِيثُ الشَّرِيفُ كَلَامُ النَّبِيِّ نَتَعَلَّمُ مِنْه.","خبيث":"الْخَبِيثُ هُوَ السَّيِّئُ الَّذِي نَبْتَعِدُ عَنْه.","نفث":"النَّفْثُ هُوَ نَفْخٌ خَفِيفٌ مَعَ رِيق.","وراث":"الْوُرَّاثُ هُمُ الَّذِينَ يَرِثُونَ مَنْ سَبَقَهُم.","تراث":"التُّرَاثُ مَا وَرِثْنَاهُ مِنْ عِلْمٍ وَحَضَارَة.","ميراث":"الْمِيرَاثُ مَا يَتْرُكُهُ الْإِنْسَانُ لِأَهْلِهِ بَعْدَه.","ثعالب":"الثَّعَالِبُ حَيَوَانَاتٌ ذَكِيَّةٌ مَاكِرَة.","ثمرات":"الثَّمَرَاتُ خَيْرَاتٌ كَثِيرَةٌ مِنَ الْأَشْجَار.","ثعبان":"الثُّعْبَانُ زَاحِفٌ طَوِيلٌ نَحْذَرُ مِنْه.","كثافة":"الْكَثَافَةُ تَعْنِي ازْدِحَامَ الشَّيْءِ وَتَرَاكُمَه.","مثلث":"الْمُثَلَّثُ شَكْلٌ لَهُ ثَلَاثَةُ أَضْلَاع.","حثيث":"السَّعْيُ الْحَثِيثُ هُوَ الْجَادُّ السَّرِيع.","أثير":"الْأَثِيرُ هُوَ الْعَزِيزُ الْمُفَضَّلُ الْمُحَبَّب.","رثاثة":"الرَّثَاثَةُ هِيَ الْقِدَمُ وَالْبِلَى.","دثور":"الدُّثُورُ جَمْعُ دِثَارٍ، وَهِيَ الْأَغْطِيَة.","تشبث":"التَّشَبُّثُ هُوَ التَّمَسُّكُ الشَّدِيدُ بِالشَّيْء.","تبعث":"تَبْعَثُ يَعْنِي تُرْسِلُ وَتُحْيِي.","منبعث":"الْمُنْبَعِثُ هُوَ الْخَارِجُ وَالصَّادِرُ مِنْ شَيْء.","موروث":"الْمَوْرُوثُ مَا نَرِثُهُ مِمَّنْ كَانَ قَبْلَنَا.","جسر":"الْجِسْرُ يَصِلُ بَيْنَ ضِفَّتَيْنِ لِنَعْبُرَ عَلَيْه.","سجد":"سَجَدَ يَعْنِي وَضَعَ جَبْهَتَهُ عَلَى الْأَرْضِ لِلَّه.","فجر":"الْفَجْرُ أَوَّلُ ضَوْءٍ يَظْهَرُ قَبْلَ الشُّرُوق.","زجل":"الزَّجَلُ نَوْعٌ مِنَ الشِّعْرِ الشَّعْبِيّ.","دجل":"الدَّجَلُ هُوَ الْكَذِبُ وَالْخِدَاع.","نضج":"نَضَجَ الثَّمَرُ يَعْنِي اكْتَمَلَ وَصَارَ صَالِحًا لِلْأَكْل.","سمج":"السَّمِجُ هُوَ الْقَبِيحُ غَيْرُ الْمُسْتَحْسَن.","خرج":"خَرَجَ يَعْنِي غَادَرَ الْمَكَانَ إِلَى الْخَارِج.","جبال":"الْجِبَالُ شَامِخَةٌ، آيَةٌ مِنْ آيَاتِ اللَّه.","سجاد":"السَّجَّادُ نَفْرُشُهُ فَيُزَيِّنُ بُيُوتَنَا.","فجوة":"الْفَجْوَةُ فُرْجَةٌ وَفَرَاغٌ بَيْنَ شَيْئَيْن.","رجال":"الرِّجَالُ يَعْمَلُونَ وَيَسْعَوْنَ لِخَيْرِ أُسَرِهِم.","نسيج":"النَّسِيجُ قُمَاشٌ نَصْنَعُ مِنْهُ الثِّيَاب.","بهيج":"الْبَهِيجُ هُوَ الْجَمِيلُ الْمُفْرِحُ لِلنَّظَر.","سميج":"السَّمِيجُ هُوَ غَيْرُ الْحَسَنِ فِي مَنْظَرِه.","رواج":"الرَّوَاجُ يَعْنِي كَثْرَةَ الطَّلَبِ وَالِانْتِشَار.","زواج":"الزَّوَاجُ سُنَّةٌ يَبْنِي بِهَا النَّاسُ أُسَرًا.","مزاج":"الْمِزَاجُ هُوَ حَالُ النَّفْسِ مِنْ فَرَحٍ أَوْ حُزْن.","جمهور":"الْجُمْهُورُ هُوَ جَمَاعَةُ النَّاسِ الْمُجْتَمِعِين.","جواهر":"الْجَوَاهِرُ أَحْجَارٌ كَرِيمَةٌ ثَمِينَة.","جبروت":"الْجَبَرُوتُ هُوَ الْعَظَمَةُ وَالْقُوَّةُ، وَهِيَ لِلَّهِ وَحْدَه.","نجوم":"النُّجُومُ تُزَيِّنُ السَّمَاءَ وَتَهْدِينَا فِي اللَّيْل.","سجود":"السُّجُودُ أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّه.","فجور":"الْفُجُورُ هُوَ الْخُرُوجُ عَنِ الْحَقِّ، نَبْتَعِدُ عَنْه.","رجاء":"الرَّجَاءُ هُوَ الْأَمَلُ وَحُسْنُ الظَّنِّ بِاللَّه.","نهج":"النَّهْجُ هُوَ الطَّرِيقُ وَالْأُسْلُوبُ الَّذِي نَسِيرُ عَلَيْه.","ازدواج":"الِازْدِوَاجُ يَعْنِي وُجُودَ الشَّيْءِ مَرَّتَيْن.","امتزاج":"الِامْتِزَاجُ هُوَ اخْتِلَاطُ الْأَشْيَاءِ مَعًا.","انزعاج":"الِانْزِعَاجُ ضِيقٌ يَزُولُ بِالصَّبْرِ وَالْهُدُوء.","كتب":"الْكُتُبُ خَيْرُ جَلِيسٍ، نَقْرَأُ فِيهَا وَنَتَعَلَّم.","رتيبة":"الْحَيَاةُ الرَّتِيبَةُ هِيَ الَّتِي لَا تَتَغَيَّر.","نبت":"نَبَتَ الزَّرْعُ يَعْنِي خَرَجَ مِنَ الْأَرْضِ وَنَمَا.","جمال":"الْجَمَالُ نِعْمَةٌ، وَجَمَالُ الْأَخْلَاقِ أَبْقَى.","فستان":"الْفُسْتَانُ لِبَاسٌ جَمِيلٌ تَرْتَدِيهِ الْبَنَات.","تنور":"التَّنُّورُ فُرْنٌ نَخْبِزُ فِيهِ الْخُبْزَ.","دثر":"دَثَّرَ يَعْنِي غَطَّى وَسَتَّرَ بِالثِّيَابِ.","ملخ":"مَلَخَ: كَيَّفَهُ بِالتَّمْرِينِ.","فرخ":"الْفَرْخُ صَغِيرُ الطَّائِرِ.","تنسخ":"تَنْسَخُ الْمُوَظَّفَةُ الْوَرَقَةَ.","مسخ":"مَسَخَ اللهُ الْمُجْرِمِينَ قِرَدَةً.","وسادة":"الْوِسَادَةُ مِخَدَّةٌ تَقْلِيدِيَّةٌ مِنَ الْقُطْنِ أَوِ الصُّوفِ.","وشق":"الْوَشَقُ حَيَوَانٌ مِنْ فَصِيلَةِ الْقِطَطِ.","جحش":"الْجَحَشُ حَيَوَانٌ عَاشِبٌ.","رخيص":"الرَّخِيصُ هُوَ الَّذِي ثَمَنُهُ قَلِيلٌ.","وضوء":"الْوُضُوءُ شَرْطُ الصَّلَاةِ.","حوض":"حَوْضُ السَّمَكِ نَظِيفٌ وَمَاؤُهُ نَقِيٌّ.","تمضمض":"تَمَضْمَضَ الرَّجُلُ بَعْدَ الطَّعَامِ.","استعاض":"اِسْتَعَاضَ الطِّفْلُ بِالْحَلِيبِ عَنِ الْحَلْوَى.","رطب":"الرُّطَبُ نَوْعٌ مِنَ التَّمْرِ.","فرط":"فَرَطَ الْعِقْدُ عَنْ خَيْطِهِ.","لحظ":"لَحَظَ الطِّفْلُ عُصْفُورًا عَلَى الشَّجَرَةِ.","أظافر":"يَجِبُ قَصُّ الْأَظَافِرِ كُلَّ أُسْبُوعَيْنِ.","وعل":"الْوَعْلُ حَيَوَانٌ يَعِيشُ فِي الْجِبَالِ.","صبغ":"صَبَغَ الْعَامِلُ الثِّيَابَ بِالْأَلْوَانِ.","يدمغ":"يَدْمَغُ الْمُوَظَّفُ الْمَلَفَّ بِخَتْمٍ رَسْمِيٍّ.","يبلغ":"يَبْلُغُ الْمُسَافِرُ غَايَتَهُ بَعْدَ عَنَاءٍ.","وغرة":"تَرَكَتِ الشَّمْسُ فِي جَوِّهِ وَغْرَةً.","صياغ":"صِيَاغُ الْمِهْنِيِّ مِنَ الذَّهَبِ عِقْدًا.","مضغ":"مَضَغَ الطَّعَامَ بِأَسْنَانِهِ جَيِّدًا.","عرف":"عَرَفَ الْمُذْنِبُ بِخَطَئِهِ فَاسْتَغْفَرَ رَبَّهُ.","عدل":"الْعَدْلُ أَسَاسُ الْمُلْكِ.","دمج":"دَمَجَ التِّلْمِيذُ صُورَتَيْنِ فِي صُورَةٍ وَاحِدَةٍ.","علم":"عَلَمُ بِلَادِي يُرَفْرِفُ عَالِيًا.","ظلم":"الظُّلْمُ أَنْ تَأْخُذَ حَقَّ غَيْرِكَ.","ردم":"رَدَمَ الرَّجُلُ الْحُفْرَةَ بِالتُّرَابِ.","دنا":"ثُمَّ دَنَا فَتَدَلَّى.","مرن":"الرِّيَاضَةُ تَجْعَلُ الْجِسْمَ مَرِنًا.","وهم":"الْوَهْمُ الشَّيْءُ الْخَيَالِيُّ غَيْرُ الْحَقِيقِيِّ.","رفاه":"الرَّفَاهُ الْعَيْشُ الطَّيِّبُ وَالْحَيَاةُ الرَّغِيدَةُ.","سري":"تَذَكَّرْ أَنَّهُ مَا دَارَ بَيْنَنَا سِرِّيٌّ جِدًّا.","أزياء":"الْأَزْيَاءُ أَشْكَالُ الْمَلَابِسِ الْجَدِيدَةِ.","أولوي":"الْأَوْلَوِيُّ هُوَ مَا يَجِبُ عَمَلُهُ أَوَّلًا.","ودي":"كَانَ يَتَعَامَلُ مَعَهُ وُدِّيًّا جِدًّا.","انقض":"اِنْقَضَّ الْقِطُّ عَلَى الْفَأْرِ."};
